  {"id": "egypt-koshari", "name": "Koshari", "nameAlt": "Rice, Lentils & Pasta", "aliases": ["Koshary"], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": ["street-food", "everyday"], "ingredients": "40g rice · 30g brown lentils · 40g elbow macaroni · 30g chickpeas (cooked) · 50g onion (crispy topping) · 80g tomato sauce (garlic & vinegar) · 10ml veg oil · cumin, salt, chilli", "method": "Cook the rice, lentils, macaroni and chickpeas separately until tender. Make a garlicky tomato sauce sharpened with vinegar and cumin. Fry the sliced onion until deep golden and crisp. Layer the rice, lentils, pasta and chickpeas, top with the sauce and crispy onions, and serve with extra chilli sauce and lemon.", "cookTime": "45–60 min", "kcal": "~420–520 kcal", "nutrition": "Carbs 75g, Protein 15g, Fat 12g, high fibre", "storage": "Fridge 3–4 days. Reheat with a splash of water; fry leftovers for extra crisp.", "chefNotes": "Fry the onions until deep golden for the signature crunch.", "pairsWith": "Extra spicy sauce and lemon wedges.", "trivia": "A complete vegetarian meal born as affordable street food, eaten daily by millions.", "howThisFeels": "The clatter of a Cairo street cart in a bowl: crisp onions, three soft starches, and a chilli-vinegar kick that wakes the whole thing up.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-ful-medames", "name": "Ful Medames", "nameAlt": "Fava Bean Stew", "aliases": ["Ful Mudammas"], "course": "main", "type": ["main", "breakfast"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": ["everyday"], "ingredients": "100g dried fava beans (soaked & cooked) · 10ml olive oil · 5g garlic · 5ml lemon juice · 3g cumin · salt, chilli flakes · parsley & tomato (garnish)", "method": "Soak and cook the fava beans until very soft (or use cooked beans). Mash some of them for a creamy texture. Stir through the olive oil, garlic, lemon, cumin, salt and chilli, loosening with a little cooking water. Top with parsley and tomato; serve warm with pita.", "cookTime": "20–30 min (after overnight soak)", "kcal": "~280–340 kcal", "nutrition": "Protein 18g, Carbs 40g, Fat 10g, high fibre & iron", "storage": "Fridge 4 days. Mash and use as a sandwich spread.", "chefNotes": "Mash partially for a creamy texture.", "pairsWith": "Aish baladi (pita), boiled eggs, pickles.", "trivia": "One of the oldest dishes in the world — remnants found in ancient tombs.", "howThisFeels": "Older than the pyramids and just as steady — the garlicky breakfast that's fed people for four thousand mornings.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-molokhia", "name": "Molokhia", "nameAlt": "Jute Leaf Stew", "aliases": ["Mulukhiyah"], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": [], "ingredients": "40g molokhia leaves (dried/frozen, chopped) · 150g chicken · 10ml ghee · 8g garlic · 5g ground coriander · 200ml chicken stock · salt, chilli", "method": "Simmer the chicken in stock until tender; keep the broth. Stir the chopped molokhia into the hot broth and simmer gently (don't boil hard). Fry the garlic and ground coriander in ghee until fragrant (the \"ta'leya\") and stir it through. Season; serve over rice with lime.", "cookTime": "40–55 min", "kcal": "~320–400 kcal", "nutrition": "Protein 28g, Fat 18g, Carbs 12g; very high in vitamins A & C", "storage": "Fridge 3 days; reheat gently.", "chefNotes": "Sauté the garlic and coriander vigorously for the signature aroma. Chicken or rabbit both work; use oil instead of ghee if you prefer.", "pairsWith": "Rice, lime, bread.", "trivia": "An ancient dish mentioned in Pharaonic texts; loved or hated for its slippery texture.", "howThisFeels": "Green, garlicky and gloriously slippery — a spoonful tastes like a grandmother's kitchen at noon.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-taameya", "name": "Taameya", "nameAlt": "Egyptian Falafel", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": [], "ingredients": "80g dried fava beans (soaked) · 30g herbs (parsley, coriander) · 20g onion · 5g garlic · 3g cumin + coriander · salt, chilli · 15ml frying oil (absorbed)", "method": "Blend the soaked fava beans with the herbs, onion, garlic and spices into a coarse green paste; rest. Shape into small patties, dip in sesame if liked, and deep-fry until deep golden and crisp; drain.", "cookTime": "25–35 min (after soaking)", "kcal": "~280–340 kcal", "nutrition": "Protein 14g, Fat 16g, Carbs 28g", "storage": "Best fresh.", "chefNotes": "Blend coarsely for texture; rest the batter.", "pairsWith": "Tahini sauce, salad, pita.", "trivia": "Made with fava beans, not chickpeas — lighter and greener than other falafel.", "howThisFeels": "Bright green inside, shatter-crisp outside — falafel the way the Nile invented it.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-mahshi", "name": "Mahshi", "nameAlt": "Stuffed Vegetables", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": ["celebration"], "ingredients": "150g mixed veg (cabbage leaves, peppers) · 60g rice filling (herbs, tomato, onion) · 100ml tomato sauce · 10ml olive oil · dill, mint, cumin", "method": "Make a rice filling with herbs, tomato and onion. Blanch the cabbage leaves (or hollow the peppers/zucchini) and stuff loosely with the rice. Pack tightly in a pot, pour over the tomato sauce/stock and oil, weigh down, and simmer gently 50–60 min until the rice is cooked.", "cookTime": "50–70 min", "kcal": "~320–380 kcal", "nutrition": "Carbs 45g, Protein 8g, Fat 12g", "storage": "Fridge 3–4 days; excellent cold next day.", "chefNotes": "Roll and layer tightly; cook low and slow. Use stock instead of the tomato sauce for a lighter braise.", "pairsWith": "Yogurt or lemon.", "trivia": "A labour of love prepared communally for family gatherings.", "howThisFeels": "Little parcels rolled by a dozen hands at once — patience you can actually taste.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-hawawshi", "name": "Hawawshi", "nameAlt": "Stuffed Pita", "aliases": [], "course": "main", "type": ["main", "snack"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": ["street-food"], "ingredients": "150g minced beef · 30g onion · 20g green peppers · 5g garlic · 1 pita (80g) · 5ml oil · cumin, chilli", "method": "Mix the minced meat with the onion, peppers, garlic and spices. Split the pita and stuff with the raw mixture, press flat and seal. Brush with oil and bake at 200°C 20–30 min, turning once, until the meat is cooked and the bread is crisp.", "cookTime": "25–35 min", "kcal": "~450–520 kcal", "nutrition": "Protein 30g, Fat 22g, Carbs 35g", "storage": "Best fresh.", "chefNotes": "Seal the pita well; bake until crispy. Beef or lamb both work.", "pairsWith": "Pickles and tahini.", "trivia": "A popular street sandwich, especially in Cairo.", "howThisFeels": "Spiced meat sizzling inside crackling bread — the smell that pulls you down a Cairo alley after dark.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-basbousa", "name": "Basbousa", "nameAlt": "Semolina Syrup Cake", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": ["celebration"], "ingredients": "60g semolina · 30g yogurt · 20g sugar · 15g butter · 5g coconut (optional) · 40ml sugar syrup (orange blossom)", "method": "Mix the semolina, yogurt, sugar, melted butter and coconut into a batter. Spread in a tray, score into diamonds, and bake at 180°C 30–40 min until golden. Pour cold orange-blossom syrup over the hot cake and let it soak.", "cookTime": "40–50 min", "kcal": "~260–320 kcal", "nutrition": "Carbs 45g, Fat 10g, Protein 6g", "storage": "Airtight, 4–5 days.", "chefNotes": "Pour cold syrup over the hot cake (or hot syrup over cold) for the best soak.", "pairsWith": "Tea, or after a heavy meal.", "trivia": "Everywhere at celebrations — the sticky sweetness is addictive.", "howThisFeels": "Sticky, syrup-soaked and sunny — the square that disappears first at every celebration.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-sayadeya", "name": "Sayadeya", "nameAlt": "Fish with Rice", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": [], "ingredients": "150g white fish fillets (tilapia/mullet) · 70g long-grain rice · 50g onion · 30g tomato paste · 5g garlic · 5g cumin + coriander · 10ml lemon juice · 15ml veg oil · 150ml fish stock", "method": "Caramelise the onions slowly in oil until deep brown, then add the tomato paste, garlic and spices. Add the rice and fish stock and cook until the rice is tender and richly coloured. Separately fry the seasoned fish until golden. Serve the fish on the rice with lemon and tahini.", "cookTime": "45–60 min", "kcal": "~380–460 kcal", "nutrition": "Protein 28g, Carbs 45g, Fat 14g, high omega-3", "storage": "Fridge 2–3 days; reheat the fish separately to keep it crisp.", "chefNotes": "Caramelise the onions well for a deep flavour base.", "pairsWith": "Tahini sauce and lemon wedges.", "trivia": "Alexandria's signature dish, from Egypt's Mediterranean coast.", "howThisFeels": "Caramel-brown rice and tender fish — a Mediterranean breeze off Alexandria on a plate.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-bamya", "name": "Bamya", "nameAlt": "Okra Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": [], "ingredients": "150g lamb · 150g okra (fresh/frozen) · 60g tomatoes (blended) · 30g onion · 5g garlic · 10ml olive oil · 5g ground coriander · 100ml stock · lemon juice", "method": "Brown the meat, then soften the onion and garlic. Add the blended tomato, ground coriander and stock and simmer until the meat is tender. Add the okra and a squeeze of lemon (to stop it going slimy) and simmer 15–20 min until tender.", "cookTime": "50–65 min", "kcal": "~340–410 kcal", "nutrition": "Protein 25g, Fat 18g, Carbs 15g, high fibre & vitamin C", "storage": "Fridge 3–4 days; flavours improve next day.", "chefNotes": "Add lemon to keep the okra from becoming slimy. Lamb or beef both work.", "pairsWith": "Rice or pita.", "trivia": "A beloved summer dish; okra is prized in Egyptian home cooking.", "howThisFeels": "Tomatoey, tender and unhurried — okra simmered the way Egyptian summers slow everything down.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-kofta-kebab", "name": "Kofta Kebab", "nameAlt": "Grilled Minced Meat", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": ["street-food"], "ingredients": "160g minced beef · 40g grated onion · 5g garlic · 5g parsley · 5g spices (cumin, coriander, allspice) · 5ml oil · salt, chilli", "method": "Mix the minced meat with the grated onion, garlic, parsley and spices; knead well and chill. Shape onto skewers and grill over high heat 8–12 min, turning, until charred and just cooked. Serve with pita, tahini, onion and tomato.", "cookTime": "20–30 min", "kcal": "~380–450 kcal", "nutrition": "Protein 32g, Fat 24g, Carbs 6g", "storage": "Fridge 3 days (raw) / 2 days (cooked). Chop into rice or wraps.", "chefNotes": "Mix the meat thoroughly and chill before grilling. Beef or lamb both work.", "pairsWith": "Pita, tahini, onions, tomatoes.", "trivia": "Essential at Egyptian barbecues and street carts.", "howThisFeels": "Charcoal smoke, grated onion and warm spice — the sound of a street grill at dusk.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-umm-ali", "name": "Umm Ali", "nameAlt": "Bread Pudding", "aliases": ["Om Ali"], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": [], "ingredients": "60g puff pastry (baked & broken) · 150ml milk · 20g mixed nuts (almonds, walnuts, raisins) · 15g sugar · 10g butter · 5ml vanilla + rose water · coconut (optional)", "method": "Bake and break the puff pastry/phyllo into a dish; scatter with the nuts and raisins. Warm the milk with the sugar, vanilla and rose water and pour over. Dot with butter and bake at 180°C 20–25 min until bubbling and golden on top.", "cookTime": "30–40 min", "kcal": "~320–380 kcal", "nutrition": "Carbs 35g, Fat 18g, Protein 8g", "storage": "Fridge 3 days; reheat in the oven to crisp.", "chefNotes": "Use plenty of butter between the layers. Phyllo works instead of puff pastry.", "pairsWith": "Hot tea, or after a heavy meal.", "trivia": "Named after a legendary Egyptian woman — rich and comforting.", "howThisFeels": "Warm, creamy and nutty — the pudding named for a queen that feels like being tucked in.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-feteer-meshaltet", "name": "Feteer Meshaltet", "nameAlt": "Layered Pastry", "aliases": [], "course": "main", "type": ["main", "breakfast"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": ["celebration"], "ingredients": "80g flour · 40g butter (layering) · 5g salt · 40g cheese (filling, optional) · icing sugar (sweet version)", "method": "Make a simple flour-salt dough and rest. Stretch it tissue-thin, brush generously with butter/ghee, and fold over and over into layers (with filling if using). Bake at 200°C 20–30 min until flaky and golden. Dust with icing sugar for the sweet version.", "cookTime": "25–35 min", "kcal": "~380–460 kcal", "nutrition": "Carbs 45g, Fat 22g", "storage": "Best fresh; fridge 2 days.", "chefNotes": "Stretch the dough very thin and fold many times. Brush with ghee instead of butter if you like; fill with cheese, minced meat or sugar & honey — or leave plain.", "pairsWith": "Honey for sweet; tea for savoury.", "trivia": "Often called \"Egyptian pizza\"; a festive treat for guests.", "howThisFeels": "Buttery layers that flake into the air — the festive pastry saved for honoured guests.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-kibda", "name": "Kibda", "nameAlt": "Liver", "aliases": [], "course": "starter", "type": ["starter", "main"], "diet": [], "cuisine": "north-africa", "country": "Egypt", "occasion": ["street-food"], "ingredients": "120g fresh calf's liver (sliced) · 30g onion · 20g green peppers · 5g garlic · 5g cumin + coriander · 10ml oil · lemon juice, chilli · salt", "method": "Slice the liver thin. Sear quickly in hot oil with the garlic, then add the onion, peppers, cumin and coriander and stir-fry just a few minutes until the liver is browned but still tender. Finish with lemon and chilli; don't overcook.", "cookTime": "15–20 min", "kcal": "~260–320 kcal", "nutrition": "Protein 28g, Fat 14g, iron-rich", "storage": "Best fresh.", "chefNotes": "Cook quickly on high heat to keep it tender.", "pairsWith": "Pita and pickles.", "trivia": "Iconic Cairo street food, famously eaten late at night.", "howThisFeels": "Peppery liver hissing in a pan at midnight — Cairo's late-night confession food.", "servings": 1, "sharedWith": ""},
  {"id": "egypt-kunafa", "name": "Kunafa", "nameAlt": "Cheese Pastry Dessert", "aliases": ["Konafa"], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Egypt", "occasion": ["ramadan", "eid"], "ingredients": "60g kunafa pastry (shredded phyllo) · 50g mozzarella · 20g melted butter · 30ml sugar syrup (rose/orange blossom) · 15g crushed pistachios", "method": "Toss the shredded kunafa pastry with the melted butter. Press half into a tray, layer the cheese, top with the rest of the pastry and press down. Bake at 200°C until golden and crisp. Pour over hot syrup straight away and scatter with crushed pistachios.", "cookTime": "30–40 min", "kcal": "~340–400 kcal", "nutrition": "Carbs 45g, Fat 16g, Protein 8g", "storage": "Best fresh; fridge 2–3 days.", "chefNotes": "Bake until golden and pour the hot syrup over immediately. Sweet cheese (akkawi) works instead of mozzarella.", "pairsWith": "Clotted cream (qishta).", "trivia": "A Ramadan and Eid favourite — the hot-crispy, sweet-cheesy contrast is irresistible.", "howThisFeels": "Crisp golden threads over molten cheese — the hot-and-sweet pull that ends a Ramadan night.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-injera", "name": "Injera", "nameAlt": "Teff Flatbread", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": [], "ingredients": "80g teff flour · 20g wheat flour (optional) · 250ml water · pinch salt", "method": "Mix the teff (and barley/wheat) flour with the water into a smooth batter and leave to ferment 2–3 days until sour and bubbly. Thin to a pourable consistency. Pour in a spiral onto a hot nonstick pan, cover to steam, and cook on one side only until the surface sets with holes. Don't flip.", "cookTime": "30–40 min active (+ 2–3 days fermenting)", "kcal": "~220–260 kcal", "nutrition": "Carbs 45g, Protein 8g, fibre 6g; high in calcium & iron", "storage": "Best fresh; fridge 2–3 days or freeze. Use day-old injera for firfir.", "chefNotes": "Pour in a spiral on a hot pan and cover to steam. A little barley or wheat flour can stand in for some of the teff.", "pairsWith": "Any wat or tibs.", "trivia": "Torn with the right hand to scoop food; teff is Ethiopia's ancient super-grain.", "howThisFeels": "Tangy, soft and full of holes — the sour pancake that's plate, spoon and supper all at once.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-doro-wat", "name": "Doro Wat", "nameAlt": "Chicken Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["celebration"], "ingredients": "200g bone-in chicken · 80g onion (finely chopped) · 20g berbere · 10g niter kibbeh (spiced butter) · 3g garlic · 2g ginger · 1 hard-boiled egg · 100ml stock · salt", "method": "Cook the finely chopped onion (no oil) until soft, then add the niter kibbeh, garlic, ginger and berbere and cook to a deep paste. Add the chicken and stock and simmer 45–60 min until very tender and the sauce is thick and red. Add the hard-boiled eggs to warm through. Season.", "cookTime": "60–75 min", "kcal": "~380–460 kcal", "nutrition": "Protein 35g, Fat 22g, Carbs 12g", "storage": "Fridge 3–4 days; flavours improve next day.", "chefNotes": "Caramelise the onions for a deep flavour base.", "pairsWith": "Injera, collard greens, ayib cheese.", "trivia": "A holiday dish; the hard-boiled egg symbolises fertility.", "howThisFeels": "Deep red, slow and ceremonial — the stew that means a holiday has arrived.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-shiro-wat", "name": "Shiro Wat", "nameAlt": "Chickpea Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["fasting", "everyday"], "ingredients": "50g shiro powder (roasted chickpea flour) · 60g onion · 10g niter kibbeh · 8g berbere · 3g garlic · 2g ginger · 200ml water · salt", "method": "Soften the onion with the garlic and ginger in niter kibbeh, then stir in the berbere. Gradually whisk in the shiro powder with the water/stock to avoid lumps. Simmer 15–20 min, stirring, until thick and smooth. Season.", "cookTime": "25–35 min", "kcal": "~280–340 kcal", "nutrition": "Protein 14g, Carbs 35g, Fat 12g, high fibre", "storage": "Fridge 4 days; reheat with extra water as it thickens.", "chefNotes": "Whisk the shiro powder in slowly to avoid lumps. Oil works instead of niter kibbeh; use stock instead of water for more depth. Authentic imported shiro powder runs ~R375/kg; roasted chickpea flour (besan) is a fine local stand-in.", "pairsWith": "Injera and fresh salad.", "trivia": "An everyday fasting food during Orthodox Christian fasts.", "howThisFeels": "Smooth, nutty and humble — the chickpea comfort that carries you through a fasting day.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-kitfo", "name": "Kitfo", "nameAlt": "Spiced Raw Beef", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["celebration"], "ingredients": "150g lean beef (freshly minced) · 8g mitmita (hot chilli blend) · 10g niter kibbeh · 5g cardamom, cloves · salt · ayib (on the side)", "method": "Warm the niter kibbeh with the mitmita, cardamom and cloves. Mix gently through the freshly minced lean beef — warm it briefly if you prefer it leb leb (rare) rather than fully raw. Season and serve straight away with ayib and gomen.", "cookTime": "10–15 min", "kcal": "~320–380 kcal", "nutrition": "Protein 32g, Fat 20g", "storage": "Best fresh, same day.", "chefNotes": "Use top-quality fresh beef; mix the spices in gently.", "pairsWith": "Injera and gomen.", "trivia": "A highlight of Gurage culture, eaten at special celebrations.", "howThisFeels": "Buttery, fiery and bold — beef warmed with spiced butter for a Gurage feast.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-tibs", "name": "Tibs", "nameAlt": "Stir-Fried Meat", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["street-food", "everyday"], "ingredients": "160g beef (cubed) · 80g onion · 50g green peppers · 10ml niter kibbeh · 5g berbere · 5g garlic · salt", "method": "Get a pan very hot with the niter kibbeh. Sear the cubed meat quickly, then add the onion, peppers, garlic and berbere (or rosemary) and stir-fry until the meat is browned and the onion softened. Season; serve sizzling.", "cookTime": "15–25 min", "kcal": "~360–430 kcal", "nutrition": "Protein 30g, Fat 22g, Carbs 10g", "storage": "Fridge 3 days; excellent in wraps next day.", "chefNotes": "Cook on high heat for the best sear. Beef or lamb both work; oil instead of niter kibbeh; rosemary for a milder spice than berbere.", "pairsWith": "Injera and awaze sauce.", "trivia": "\"Tibs\" means \"to fry\" in Amharic — a restaurant and street-food staple.", "howThisFeels": "Meat hitting a hot pan with a hiss — the word itself simply means 'to fry'.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-gomen", "name": "Gomen", "nameAlt": "Collard Greens", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": [], "ingredients": "200g kale (chopped) · 40g onion · 5g niter kibbeh · 3g garlic · 2g ginger · 3g berbere · salt", "method": "Soften the onion in niter kibbeh with the garlic and ginger. Add the chopped greens, the spice and a splash of water, and cook 15–20 min until tender but not mushy. Season.", "cookTime": "25–35 min", "kcal": "~120–160 kcal", "nutrition": "Protein 6g, Carbs 12g; high in vitamins A, C & K", "storage": "Fridge 4 days; mix into leftover injera.", "chefNotes": "Cook until tender but not mushy. Collard greens (morogo) are the traditional green — use them instead of kale if you can get them.", "pairsWith": "Doro wat or shiro.", "trivia": "A common vegetable side reflecting Ethiopia's highland farming.", "howThisFeels": "Silky greens softened in spiced butter — the quiet green heart of a highland meal.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-dabo-kolo", "name": "Dabo Kolo", "nameAlt": "Spiced Fried Dough Bites", "aliases": [], "course": "dessert", "type": ["snack", "dessert"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": [], "ingredients": "60g flour · 10g butter · 15g honey · 3g cardamom, cinnamon · 20ml milk · 10ml frying oil (absorbed)", "method": "Make a spiced dough with the flour, butter, cardamom, cinnamon, honey and milk. Roll into thin ropes and cut into small bite-size pieces. Fry (or toast in a dry pan) until golden and crunchy. Toss with a little honey while warm.", "cookTime": "25–35 min", "kcal": "~240–290 kcal", "nutrition": "Carbs 38g, Fat 10g", "storage": "Airtight, 1 week.", "chefNotes": "Cut into small pieces and fry until golden.", "pairsWith": "Ethiopian coffee.", "trivia": "A favourite during the coffee ceremony, a central social ritual.", "howThisFeels": "Tiny crunchy bites, sweet and cardamom-scented — the nibble that keeps the coffee ceremony going.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-misir-wat", "name": "Misir Wat", "nameAlt": "Red Lentil Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["fasting", "everyday"], "ingredients": "60g split red lentils · 60g onion · 10g niter kibbeh · 8g berbere · 3g garlic · 2g ginger · 200ml water · salt", "method": "Cook the finely chopped onion until very soft, then add the niter kibbeh, garlic, ginger and berbere and cook to a paste. Stir in the red lentils and water/stock and simmer 20–25 min until the lentils collapse into a thick, spicy stew. Season.", "cookTime": "30–40 min", "kcal": "~260–320 kcal", "nutrition": "Protein 16g, Carbs 38g, Fat 8g, high in iron & fibre", "storage": "Fridge 4 days; freezes well. Reheat with extra water.", "chefNotes": "Cook the onions very soft before adding the berbere. Oil works instead of niter kibbeh; stock instead of water for more depth.", "pairsWith": "Injera and ayib cheese.", "trivia": "A common \"fasting wat\" during Orthodox fasting seasons.", "howThisFeels": "Glowing red and gently spiced — the lentils that fasting days actually look forward to.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-siga-wat", "name": "Siga Wat", "nameAlt": "Beef Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["celebration"], "ingredients": "160g beef (cubed) · 80g onion · 15g berbere · 10g niter kibbeh · 3g garlic · 2g ginger · 100ml beef stock · salt", "method": "Cook the onion until soft, add the niter kibbeh, garlic, ginger and berbere and cook to a deep paste. Brown the beef, then add it with the stock and simmer 50–60 min until tender and the sauce is rich and red. Season.", "cookTime": "60–75 min", "kcal": "~360–430 kcal", "nutrition": "Protein 32g, Fat 22g, Carbs 10g", "storage": "Fridge 3–4 days; flavours deepen overnight.", "chefNotes": "Brown the meat well and cook the onions slowly for a rich base.", "pairsWith": "Injera and gomen.", "trivia": "A classic celebration dish for holidays and weddings.", "howThisFeels": "Rich, dark and celebratory — beef that knows it's bound for a wedding table.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-atikilt-wat", "name": "Atikilt Wat", "nameAlt": "Mixed Vegetable Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["fasting"], "ingredients": "100g cabbage · 60g carrots · 60g potatoes · 40g onion · 10g niter kibbeh · 5g turmeric, cumin · 5g garlic · 100ml water", "method": "Soften the onion in niter kibbeh with the garlic, turmeric and cumin. Add the carrots and potatoes with a little water and cook 10 min, then add the cabbage and simmer 15–20 min until tender but still holding their shape.", "cookTime": "35–45 min", "kcal": "~220–280 kcal", "nutrition": "Carbs 35g, Protein 6g, Fat 8g, high in vitamins", "storage": "Fridge 4 days; mash slightly and serve as a side.", "chefNotes": "Cook the vegetables tender but keep some texture. Oil works instead of niter kibbeh.", "pairsWith": "Injera with shiro or misir wat.", "trivia": "Common during fasting periods; showcases highland vegetables.", "howThisFeels": "Turmeric-gold and gentle — the mild vegetable stew that gives the fiery dishes a rest.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-sambusa", "name": "Sambusa", "nameAlt": "Samosa", "aliases": [], "course": "starter", "type": ["starter"], "diet": [], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["celebration", "street-food"], "ingredients": "60g pastry wrappers · 50g spiced lentils (filling) · 3g onion · 2g garlic · 3g berbere · 15ml frying oil (absorbed)", "method": "Fry the onion and garlic, add the lentils or beef with berbere/cumin and cook until dry; cool. Fill the wrappers, fold into triangles and seal the edges tightly. Deep-fry until golden and crisp; drain.", "cookTime": "25–35 min", "kcal": "~280–340 kcal", "nutrition": "Protein 12g, Fat 16g, Carbs 28g", "storage": "Best fresh; fridge 2 days. Reheat in the oven to crisp.", "chefNotes": "Seal the edges tightly so oil can't get in. Lentil or beef filling both work.", "pairsWith": "Awaze dipping sauce.", "trivia": "A popular street snack and party appetiser across Ethiopia.", "howThisFeels": "Crisp golden triangles, spiced and steaming — the snack that announces a party.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-firfir", "name": "Firfir", "nameAlt": "Injera-based Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": [], "ingredients": "100g torn injera · 60g berbere sauce base (from leftover wat) · 10g niter kibbeh · 5g garlic · 150ml water · onion (garnish)", "method": "Warm the leftover berbere wat sauce with the niter kibbeh and garlic, loosening with a little water/stock. Toss in the torn injera and stir gently over low heat until it soaks up the sauce and warms through. Top with fresh onion; serve with ayib.", "cookTime": "15–25 min", "kcal": "~340–400 kcal", "nutrition": "Carbs 55g, Protein 12g, Fat 12g", "storage": "Best fresh.", "chefNotes": "Simmer gently so the injera absorbs the flavours. Loosen with stock instead of water for more flavour.", "pairsWith": "Yogurt or ayib.", "trivia": "A resourceful \"leftover\" dish that's become a beloved comfort food.", "howThisFeels": "Yesterday's injera reborn in fiery sauce — proof that leftovers can be a love letter.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-ayib", "name": "Ayib", "nameAlt": "Fresh Cheese", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["everyday"], "ingredients": "80g fresh ayib cheese · pinch salt · herbs or berbere (optional, spiced version)", "method": "Gently heat fresh milk or buttermilk (or use leftover whey) just until it curdles into soft curds. Drain through a cloth and press lightly, then season with a pinch of salt (and herbs or berbere for a spiced version). Serve cool.", "cookTime": "20–30 min (if making fresh)", "kcal": "~140–180 kcal", "nutrition": "Protein 14g, Fat 8g, low carb", "storage": "Fridge 4–5 days; mix into firfir or spread on injera.", "chefNotes": "Curdle gently for a soft texture.", "pairsWith": "Almost any wat or kitfo.", "trivia": "Ethiopia's everyday fresh cheese, often made at home.", "howThisFeels": "Cool, mild and crumbly — the fresh cheese that calms a spiced plate down.", "servings": 1, "sharedWith": ""},
  {"id": "ethiopia-himbasha", "name": "Himbasha", "nameAlt": "Sweet Bread", "aliases": [], "course": "dessert", "type": ["dessert", "breakfast"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Ethiopia", "occasion": ["celebration"], "ingredients": "70g flour · 10g sugar · 5g yeast · 30ml milk · 5g raisins · 2g cardamom · 5g butter", "method": "Mix the flour, sugar, yeast, cardamom and butter with the warm milk into a soft dough; knead and prove until doubled (about 1 hr). Work in the raisins, shape into a round and score a decorative pattern on top. Bake at 180°C 25–30 min until golden.", "cookTime": "40–50 min", "kcal": "~260–310 kcal", "nutrition": "Carbs 48g, Protein 8g, Fat 6g", "storage": "Airtight, 3–4 days.", "chefNotes": "Score a decorative pattern on top before baking.", "pairsWith": "Ethiopian coffee or tea.", "trivia": "Traditionally served during holidays and coffee ceremonies.", "howThisFeels": "Faintly sweet, cardamom-warm and pressed with a pattern — bread baked for the good days.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-ugali", "name": "Ugali", "nameAlt": "Maize Porridge", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["everyday"], "ingredients": "100g maize meal (white) · 400ml water · 2g salt", "method": "Bring the salted water to the boil. Gradually add the maize meal, stirring hard with a wooden spoon. Keep stirring and folding over low heat until thick and pulling away from the pot (15–20 min). Shape and turn out.", "cookTime": "20–25 min", "kcal": "~350–390 kcal", "nutrition": "Carbs 75g, Protein 8g, Fat 2g, fibre 4g", "storage": "Best fresh; fridge up to 2 days. Reheat with water or fry into ugali cakes.", "chefNotes": "Stir vigorously until it pulls away from the pot.", "pairsWith": "Sukuma wiki, nyama choma, or fish stew.", "trivia": "Eaten by hand in scooping balls — a symbol of Kenyan unity across tribes.", "howThisFeels": "Plain, warm and steady in your hand — the maize that holds a Kenyan table together.", "servings": 1, "sharedWith": "Tanzania"},
  {"id": "kenya-nyama-choma", "name": "Nyama Choma", "nameAlt": "Grilled Meat", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "200g goat ribs · 5g garlic · 5g ginger · 3g salt + pepper · 10ml veg oil · lemon (serving)", "method": "Rub the meat with garlic, ginger, salt, pepper and oil; marinate (overnight for events). Grill slowly over charcoal, turning, 45–60 min until cooked through with a smoky char. Rest, cut into pieces, and serve with lemon.", "cookTime": "45–70 min", "kcal": "~380–460 kcal", "nutrition": "Protein 35g, Fat 25g, low carb", "storage": "Fridge 3 days; great cold in salads or reheated.", "chefNotes": "Grill slowly over charcoal; serve medium-well. Beef works as well as goat; chunks instead of ribs are fine.", "pairsWith": "Kachumbari and ugali.", "trivia": "The ultimate Kenyan social dish — \"choma\" means roast.", "howThisFeels": "Charcoal, salt and good company — roast meat that's really an invitation to linger.", "servings": 1, "sharedWith": "Tanzania"},
  {"id": "kenya-sukuma-wiki", "name": "Sukuma Wiki", "nameAlt": "Stewed Greens", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["everyday"], "ingredients": "200g sukuma wiki (collards/kale) · 50g onion · 5g tomato · 5g garlic · 10ml veg oil · 2g salt · chilli", "method": "Fry the onion in oil until soft, add the garlic and tomato and cook down. Add the chopped greens, bouillon/salt and chilli, and cook 10–15 min until tender but still green. A splash of milk makes it creamier.", "cookTime": "20–25 min", "kcal": "~120–160 kcal", "nutrition": "Protein 6g, Fat 8g, Carbs 12g; very high in vitamins A, C & K", "storage": "Fridge 3–4 days; mix into ugali or reheat with eggs.", "chefNotes": "Cook until tender but still vibrant. A bouillon cube instead of salt adds savoury depth.", "pairsWith": "Ugali and nyama choma.", "trivia": "The name means \"push the week\" — an affordable green that stretches the budget.", "howThisFeels": "Greens that 'push the week' along — the everyday side that stretches a little into enough.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-githeri", "name": "Githeri", "nameAlt": "Maize & Beans", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "80g maize kernels · 60g beans (kidney/pigeon peas, soaked) · 50g onion · 30g tomato · 5g garlic · 10ml oil · salt, curry powder", "method": "Soak the beans overnight, then boil with the maize until both are soft (60–90 min, or use a pressure cooker). In oil, fry the onion, garlic and tomato with the curry powder, then stir in the cooked maize and beans and simmer 10 min. Season.", "cookTime": "60–90 min", "kcal": "~320–380 kcal", "nutrition": "Protein 14g, Carbs 55g, high fibre", "storage": "Fridge 4 days; mash and fry into cakes.", "chefNotes": "Cook until soft; add coconut milk for a coastal twist.", "pairsWith": "Ugali, or as a standalone meal.", "trivia": "A humble, nutritious dish popular in central Kenya, especially among the Kikuyu.", "howThisFeels": "Maize and beans, plain and filling — the honest pot that keeps central Kenya going.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-kachumbari", "name": "Kachumbari", "nameAlt": "Tomato & Onion Salad", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "100g tomatoes (diced) · 50g red onion (sliced) · 30g cucumber (optional) · 5g coriander · 5ml lemon juice · 5g chilli · salt", "method": "Dice the tomatoes and slice the red onion thinly (rinse the onion to soften its bite). Toss with the cucumber, coriander, lemon juice, chilli and salt just before serving.", "cookTime": "10 min (no-cook)", "kcal": "~40–60 kcal", "nutrition": "Carbs 8g, high in vitamin C", "storage": "Fridge 2 days.", "chefNotes": "Mix just before serving to keep it fresh.", "pairsWith": "Nyama choma and ugali.", "trivia": "Kenya's most common fresh accompaniment — crunch and brightness for rich meals.", "howThisFeels": "Cool tomato, sharp onion and a squeeze of lime — the fresh crunch every rich plate waits for.", "servings": 1, "sharedWith": "Tanzania"},
  {"id": "kenya-mandazi", "name": "Mandazi", "nameAlt": "Coconut Fried Dough", "aliases": [], "course": "dessert", "type": ["dessert", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["breakfast", "street-food"], "ingredients": "60g flour · 10g sugar · 5g baking powder · 30ml coconut milk · 5g cardamom · 15ml frying oil (absorbed)", "method": "Mix the flour, sugar, baking powder and cardamom, then add the coconut milk to form a soft dough. Roll out, cut into triangles, and deep-fry at medium heat until puffed and golden; drain.", "cookTime": "25–35 min", "kcal": "~260–320 kcal", "nutrition": "Carbs 38g, Fat 12g", "storage": "Airtight, 2–3 days.", "chefNotes": "Knead lightly and fry at medium heat.", "pairsWith": "Chai tea.", "trivia": "A popular street snack and breakfast item across Kenya.", "howThisFeels": "Faintly sweet, coconut-soft and warm from the pan — Kenya's morning corner-shop treat.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-mukimo", "name": "Mukimo", "nameAlt": "Mashed Maize & Greens", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["celebration"], "ingredients": "100g potatoes · 50g maize kernels · 80g kale · 30g onion · 10ml veg oil · salt", "method": "Boil the potatoes and maize until soft. Wilt the greens. Mash everything together with the sautéed onion and oil while hot, until smooth and green. Season.", "cookTime": "40–50 min", "kcal": "~280–340 kcal", "nutrition": "Carbs 55g, Protein 8g, Fat 8g, high fibre & vitamins", "storage": "Fridge 3 days; reheat with water or fry as patties.", "chefNotes": "Mash while hot for a smooth texture (traditionally with a wooden pestle). Pumpkin leaves are the traditional green — use them instead of kale if you can get them.", "pairsWith": "Nyama choma or beef stew.", "trivia": "Served at weddings and celebrations; the green comes from pumpkin leaves.", "howThisFeels": "Green-flecked mash of maize and potato — the celebration dish that turns up at weddings.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-chapati", "name": "Chapati", "nameAlt": "Flatbread", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["everyday"], "ingredients": "80g wheat flour · 5g salt · 10ml veg oil · 60ml warm water · extra oil (brushing)", "method": "Make a soft dough with the flour, salt, oil and warm water; knead well and rest 30 min. Roll thin, brush with oil, coil into a spiral, then roll flat again for layers. Cook on a hot tawa with a little oil until golden and flecked, pressing for puff.", "cookTime": "30–40 min", "kcal": "~320–380 kcal", "nutrition": "Carbs 55g, Protein 10g, Fat 12g", "storage": "Airtight 2 days; reheat on a dry pan or use in wraps.", "chefNotes": "Knead well, rest the dough, and cook on a hot tawa with oil for layers.", "pairsWith": "Beef stew, beans, or sukuma wiki.", "trivia": "Introduced via Indian influence, now a Kenyan everyday essential.", "howThisFeels": "Soft, flaky and faintly charred — the flatbread Kenya borrowed and made entirely its own.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-coconut-fish-curry", "name": "Coconut Fish Curry", "nameAlt": "Samaki wa Nazi", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "180g firm white fish (tilapia/snapper) · 100ml coconut milk · 50g onion · 30g tomato · 3g garlic · 2g ginger · 5g curry powder · 8g coriander · 10ml veg oil · salt, chilli", "method": "Fry the onion, garlic and ginger in oil, add the tomato and curry powder and cook down. Pour in the coconut milk and simmer 10 min. Slide in the fish and simmer gently 8–10 min until just cooked. Finish with coriander, salt and chilli.", "cookTime": "30–40 min", "kcal": "~340–410 kcal", "nutrition": "Protein 30g, Fat 22g, Carbs 10g", "storage": "Fridge 2–3 days; reheat gently, excellent with rice.", "chefNotes": "Add the fish last so it doesn't break apart.", "pairsWith": "Coconut rice or ugali.", "trivia": "Reflects Swahili coastal heritage with Arab and Indian influences.", "howThisFeels": "Coconut, spice and ocean — the Swahili coast in one fragrant bowl.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-viazi-karai", "name": "Viazi Karai", "nameAlt": "Battered Fried Potatoes", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["street-food"], "ingredients": "150g potatoes (boiled) · 40g chickpea flour (besan) · 5g chilli powder + cumin · 3g garlic · salt · 15ml frying oil (absorbed)", "method": "Boil the potatoes, then cut into wedges. Make a batter with the chickpea flour, chilli, cumin, garlic, salt and water. Dip the potatoes and deep-fry until golden and crisp; drain.", "cookTime": "25–35 min", "kcal": "~280–340 kcal", "nutrition": "Carbs 38g, Protein 10g, Fat 14g", "storage": "Best fresh.", "chefNotes": "Cut into wedges and coat lightly in batter.", "pairsWith": "Tamarind chutney or kachumbari.", "trivia": "A popular evening street snack in Mombasa and Nairobi.", "howThisFeels": "Golden batter, soft potato and a hit of chilli — Mombasa's evening street snack.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-mchicha", "name": "Mchicha", "nameAlt": "Amaranth Greens", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "200g amaranth leaves (or spinach) · 30g onion · 10ml veg oil · 20g peanut butter · 5g garlic · salt, chilli", "method": "Fry the onion and garlic in oil. Add the chopped amaranth (or spinach) and cook until wilted. Stir in the peanut butter or coconut milk and simmer 5–8 min until creamy. Season with salt and chilli.", "cookTime": "20–25 min", "kcal": "~160–220 kcal", "nutrition": "Protein 8g, Fat 12g, Carbs 12g, iron-rich", "storage": "Fridge 3 days; mix with ugali.", "chefNotes": "Wilt the leaves quickly to keep the nutrients. Stir in 50ml coconut milk instead of peanut butter for a coastal version.", "pairsWith": "Ugali and grilled fish.", "trivia": "A nutritious traditional green widely grown on Kenyan farms.", "howThisFeels": "Iron-rich greens, simple and good — straight from the farm to the family pot.", "servings": 1, "sharedWith": "Tanzania"},
  {"id": "kenya-kenyan-beef-stew", "name": "Kenyan Beef Stew", "nameAlt": "Beef & Potato Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Kenya", "occasion": [], "ingredients": "150g beef (stewing) · 80g potatoes · 50g carrots · 50g onion · 10ml oil · 3g garlic · 2g ginger · 5g curry powder · 100ml stock", "method": "Brown the beef in oil, then soften the onion with the garlic, ginger and curry powder. Return the beef with the stock and simmer 50–60 min until tender. Add the potatoes and carrots and cook 20–30 min more until soft and the gravy thickens.", "cookTime": "70–90 min", "kcal": "~360–430 kcal", "nutrition": "Protein 28g, Carbs 25g, Fat 18g", "storage": "Fridge 3–4 days; improves overnight, serve with chapati.", "chefNotes": "Brown the meat well before adding the vegetables.", "pairsWith": "Chapati or rice.", "trivia": "A comforting homestyle dish prepared across Kenya.", "howThisFeels": "Slow beef, soft potatoes and gravy — the homestyle plate that smells like coming home.", "servings": 1, "sharedWith": ""},
  {"id": "kenya-mahamri", "name": "Mahamri", "nameAlt": "Coconut Doughnuts", "aliases": [], "course": "dessert", "type": ["dessert", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Kenya", "occasion": ["breakfast"], "ingredients": "60g flour · 10g sugar · 5g yeast · 30ml coconut milk · 3g cardamom · 15ml frying oil (absorbed)", "method": "Mix the flour, sugar, yeast and cardamom with the coconut milk into a soft dough; prove until risen. Roll out, cut into triangles, and deep-fry until puffed and golden; drain.", "cookTime": "30–45 min (incl. rising)", "kcal": "~280–340 kcal", "nutrition": "Carbs 42g, Fat 12g", "storage": "Airtight, 2 days.", "chefNotes": "Let the dough rise properly; fry until golden.", "pairsWith": "Hot chai tea.", "trivia": "A traditional Swahili breakfast treat, enjoyed with coffee or tea.", "howThisFeels": "Cardamom-and-coconut puffs — the Swahili breakfast that begs for a cup of chai.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-chicken-tagine-with-preserved-lemon-and-olives", "name": "Chicken Tagine with Preserved Lemon and Olives", "nameAlt": "Classic Moroccan Tagine", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "200g bone-in chicken thighs · 50g preserved lemon · 60g green olives · 80g onion · 5g garlic · 5g ginger · 5g ras el hanout · 10ml olive oil · 100ml stock · 5g coriander · pinch saffron", "method": "Brown the chicken in olive oil, then set aside. Soften the onion, garlic and ginger, and stir in the ras el hanout and saffron. Return the chicken with the stock, cover and simmer gently 45–60 min until tender. Add the preserved lemon and olives in the last 10 min. Finish with coriander.", "cookTime": "50–70 min", "kcal": "~380–450 kcal", "nutrition": "Protein 32g, Fat 22g, Carbs 10g; high in iron & vitamin C", "storage": "Fridge 3–4 days; flavours improve overnight.", "chefNotes": "Use a clay tagine or heavy lidded pot; add olives and lemon near the end.", "pairsWith": "Couscous or crusty bread.", "trivia": "\"Tagine\" is both the dish and the conical pot — a cornerstone of Moroccan hospitality.", "howThisFeels": "Salty olives, bright preserved lemon and meltingly slow chicken — hospitality in a cone-lidded pot.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-couscous-with-vegetables-and-lamb", "name": "Couscous with Vegetables and Lamb", "nameAlt": "Seven-Veg Couscous", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "80g dry couscous · 150g lamb shoulder (cubed) · 100g mixed veg (carrot, zucchini, pumpkin, chickpeas) · 50g onion · 5g ras el hanout · 10ml olive oil · 150ml stock · coriander, parsley", "method": "Brown the lamb, then simmer with the onion, ras el hanout and stock 45 min. Add the firmer vegetables and chickpeas and cook until tender. Meanwhile steam the couscous in stages, fluffing with a little oil between. Mound the couscous, top with the meat and vegetables, and ladle over the broth. Scatter with herbs.", "cookTime": "60–75 min", "kcal": "~420–490 kcal", "nutrition": "Carbs 55g, Protein 28g, Fat 18g, high fibre", "storage": "Fridge 3 days. Re-steam the couscous with a little water.", "chefNotes": "Steam couscous in stages for fluffiness; keep vegetables whole for presentation.", "pairsWith": "Buttermilk or harissa.", "trivia": "Eaten communally from one platter — a symbol of abundance and family unity.", "howThisFeels": "A mountain of steamed grains shared from one platter — Friday, family and abundance.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-harira", "name": "Harira", "nameAlt": "Lentil & Chickpea Soup", "aliases": [], "course": "main", "type": ["main", "soup"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": ["ramadan"], "ingredients": "40g lamb (optional) · 30g lentils · 30g chickpeas (soaked) · 80g tomatoes (blended) · 20g onion · 10g celery · 3g garlic · 2g ginger · 10ml olive oil · 5g harira spices (cumin, turmeric, cinnamon) · 200ml stock · coriander, lemon", "method": "Soften the onion and celery in olive oil with the ginger, garlic and spices. Add the meat (if using) and brown, then the blended tomatoes, lentils, chickpeas and stock. Simmer 45–60 min until the pulses are soft and the soup is rich. Finish with coriander and lemon; thicken slightly if you like.", "cookTime": "50–70 min", "kcal": "~280–350 kcal", "nutrition": "Protein 18g, Carbs 35g, high fibre & plant protein", "storage": "Fridge 4 days; freezes well. Thickens on reheating.", "chefNotes": "Add smen (aged butter) or lemon for authenticity. Beef works in place of lamb.", "pairsWith": "Dates and chebakia.", "trivia": "Morocco's national soup, eaten especially to break the Ramadan fast.", "howThisFeels": "Thick, tomatoey and restorative — the soup that breaks the fast as the sun goes down.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-pastilla", "name": "Pastilla", "nameAlt": "Sweet-Savoury Pie", "aliases": ["Bastilla"], "course": "starter", "type": ["starter", "main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "100g shredded chicken · 40g almonds (toasted, chopped) · 30g onion · 5g cinnamon, ginger · 1 beaten egg · 2–3 phyllo sheets (40g) · 10g butter · icing sugar, cinnamon (dusting)", "method": "Cook the shredded chicken with onion, cinnamon and ginger, then stir the beaten egg through to set into a soft scramble; mix in the toasted almonds. Brush phyllo sheets with butter, layer them, fill, and fold into a round pie. Bake at 180°C 25–30 min until crisp and golden. Dust with icing sugar and cinnamon just before serving.", "cookTime": "45–60 min", "kcal": "~380–450 kcal", "nutrition": "Protein 25g, Fat 22g, Carbs 28g", "storage": "Best fresh; fridge 2 days.", "chefNotes": "Layer carefully; dust with sugar only at the last moment.", "pairsWith": "Mint tea.", "trivia": "A royal dish from Fez — its sweet-savoury contrast is a hallmark of Moroccan cuisine.", "howThisFeels": "Sweet, savoury and dusted with sugar — the royal pie that tastes like a Fez palace.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-zaalouk", "name": "Zaalouk", "nameAlt": "Eggplant Salad", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["everyday"], "ingredients": "150g eggplant (cubed) · 80g tomatoes · 5g garlic · 10ml olive oil · 5g paprika, cumin · coriander · lemon juice", "method": "Char or roast the eggplant, then peel and chop. Cook the tomato, garlic, paprika and cumin in olive oil until thick. Add the eggplant and simmer, mashing, until soft and jammy. Finish with coriander and lemon. Serve warm or cold.", "cookTime": "25–35 min", "kcal": "~140–180 kcal", "nutrition": "Carbs 12g, Fat 10g, high fibre", "storage": "Fridge 4 days; great cold as a dip.", "chefNotes": "Char the eggplant for a smoky flavour.", "pairsWith": "Tagines and bread.", "trivia": "An everyday mezze at almost every Moroccan meal.", "howThisFeels": "Smoky aubergine, garlic and warm tomato — the dip that turns up at every Moroccan table.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-msemen", "name": "Msemen", "nameAlt": "Layered Flatbread", "aliases": [], "course": "side", "type": ["side", "breakfast"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["breakfast", "street-food"], "ingredients": "80g flour (mix in semolina) · 5g yeast · 80ml warm water · 5ml olive oil · pinch salt · butter (for folding)", "method": "Make a soft dough with the flour, semolina, yeast, water and salt; rest. Divide into balls, oil generously, flatten very thin, then fold into squares, trapping butter/oil in the layers. Rest again, then cook on a hot pan, pressing, until golden on both sides.", "cookTime": "30–40 min", "kcal": "~260–310 kcal", "nutrition": "Carbs 45g", "storage": "Airtight, 2 days.", "chefNotes": "Fold and flatten several times to build the layers. Baking powder works in place of yeast; brush with oil instead of butter if you prefer.", "pairsWith": "Honey, cheese, or tagine.", "trivia": "A popular street breakfast; perfect squares take practice.", "howThisFeels": "Folded, fried and faintly chewy — the square breakfast bread street stalls perfect daily.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-moroccan-mint-tea", "name": "Moroccan Mint Tea", "nameAlt": "Sweet Mint Tea", "aliases": [], "course": "drink", "type": ["drink"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "2g green tea leaves · 10–15 mint sprigs · 15g sugar · 250ml hot water", "method": "Rinse the green tea with a little hot water and discard the water. Add the mint, sugar and hot water and steep 5 min. Pour from a height into glasses to build foam; serve hot.", "cookTime": "10–15 min", "kcal": "~60–80 kcal", "nutrition": "low calorie, antioxidants", "storage": "Best fresh.", "chefNotes": "Pour from a height for the signature foam.", "pairsWith": "Any meal or pastries.", "trivia": "Called \"Moroccan whiskey\"; hospitality dictates it's served in three rounds.", "howThisFeels": "Poured high and sweet, three rounds deep — a glass of welcome you can almost hear hiss.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-lamb-tagine-with-prunes-and-almonds", "name": "Lamb Tagine with Prunes and Almonds", "nameAlt": "Sweet & Savoury Tagine", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": ["eid", "celebration"], "ingredients": "180g lamb shoulder (cubed) · 60g prunes · 30g blanched almonds (toasted) · 80g onion · 5g garlic · 5g ginger · 5g ras el hanout · 2g cinnamon · 10ml olive oil · 15g honey · 100ml water · sesame seeds", "method": "Brown the lamb, then soften the onion, garlic and ginger with the ras el hanout and cinnamon. Add the lamb and water/stock, cover and simmer 60–70 min until tender. Add the prunes and honey in the last 15 min and reduce until glossy. Scatter with toasted almonds and sesame.", "cookTime": "60–80 min", "kcal": "~420–490 kcal", "nutrition": "Protein 30g, Fat 24g, Carbs 25g, rich in iron", "storage": "Fridge 3–4 days; flavours meld, reheat slowly.", "chefNotes": "Brown the meat first; add honey near the end for a glossy sauce.", "pairsWith": "Couscous or crusty bread.", "trivia": "A festive dish for weddings and Eid — sweet prunes against tender lamb.", "howThisFeels": "Sweet prunes against tender lamb — the festive tagine that means a wedding's underway.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-kefta-tagine-with-eggs", "name": "Kefta Tagine with Eggs", "nameAlt": "Meatball & Egg Tagine", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": ["street-food", "everyday"], "ingredients": "150g minced beef · 50g grated onion · 5g garlic · 5g parsley, coriander · 5g cumin, paprika · 10ml olive oil · 80g tomatoes (blended) · 2 eggs · chilli, salt", "method": "Mix the mince with the grated onion, garlic, herbs and spices and roll into small meatballs. Brown them, then add the blended tomato and chilli and simmer 15 min until saucy. Make wells and crack in the eggs; cover and cook until just set. Serve with bread.", "cookTime": "35–45 min", "kcal": "~380–440 kcal", "nutrition": "Protein 32g, Fat 25g, Carbs 8g", "storage": "Fridge 3 days; reheat and add fresh eggs if you like.", "chefNotes": "Poach the eggs in the sauce right at the end. Lamb mince works just as well as beef.", "pairsWith": "Bread for scooping.", "trivia": "An everyday favourite, big at street stalls and casual meals.", "howThisFeels": "Spiced meatballs bubbling in tomato with eggs cracked on top — comfort straight from the pan.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-taktouka", "name": "Taktouka", "nameAlt": "Roasted Pepper Salad", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["everyday"], "ingredients": "120g green peppers (roasted) · 100g tomatoes · 5g garlic · 10ml olive oil · 3g paprika, cumin · parsley · lemon juice", "method": "Roast and peel the green peppers, then chop. Cook the tomato, garlic, paprika and cumin in olive oil until thick. Add the peppers and simmer until soft and jammy. Finish with parsley and lemon; serve warm or cold.", "cookTime": "25–35 min", "kcal": "~130–170 kcal", "nutrition": "Carbs 12g, Fat 9g, high in vitamin C", "storage": "Fridge 4 days; serve cold as a dip with bread.", "chefNotes": "Char the peppers for smoky depth.", "pairsWith": "Tagines, or as part of a mezze spread.", "trivia": "A staple cooked salad served before the mains.", "howThisFeels": "Roasted peppers and tomato cooked down soft — the warm salad that opens the meal.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-bissara", "name": "Bissara", "nameAlt": "Fava Bean Soup", "aliases": [], "course": "main", "type": ["main", "starter"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "80g dried fava beans (soaked) · 30g onion · 5g garlic · 5g cumin + paprika · 10ml olive oil · 200ml water · coriander, olive oil to drizzle", "method": "Soak the fava beans, then boil with the onion, garlic and spices until very soft (45–60 min). Blend until smooth, loosening with the cooking liquid or stock. Reheat, season, and serve drizzled with olive oil and a dusting of cumin and paprika.", "cookTime": "50–70 min (after soaking)", "kcal": "~240–300 kcal", "nutrition": "Protein 15g, Carbs 35g, high fibre", "storage": "Fridge 4 days; freezes well. Thin with stock to reheat.", "chefNotes": "Blend very smooth; drizzle good olive oil on top.", "pairsWith": "Bread and olives.", "trivia": "A traditional winter warmer, especially in northern Morocco.", "howThisFeels": "Velvety fava bean soup under a drizzle of oil — a northern Moroccan winter in a bowl.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-chebakia", "name": "Chebakia", "nameAlt": "Sesame Honey Cookies", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["ramadan"], "ingredients": "35g flour · 15g ground almonds · 20g sesame seeds (toasted) · 10g butter · 5g anise, cinnamon · ¼ egg · 30ml orange blossom water · 30ml honey (soaking)", "method": "Make a spiced dough with the flour, almond meal, butter, anise, cinnamon, egg and orange blossom water. Roll, cut and fold into flower shapes. Deep-fry until golden, then immediately plunge into warm honey for a minute. Drain and roll in toasted sesame.", "cookTime": "40–50 min", "kcal": "~280–340 kcal", "nutrition": "Carbs 35g, Fat 14g, Protein 6g", "storage": "Airtight, up to 2 weeks.", "chefNotes": "Fry until golden, then soak in warm honey straight away.", "pairsWith": "Mint tea.", "trivia": "Essential during Ramadan; the flower shape takes practice.", "howThisFeels": "Sesame-crusted, honey-soaked flowers — the Ramadan cookie folded by patient hands.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-rfissa", "name": "Rfissa", "nameAlt": "Chicken, Lentil & Msemen", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "150g chicken pieces · 40g lentils · 2–3 msemen (shredded, ~80g) · 5g fenugreek seeds (soaked) · 50g onion · 5g ras el hanout, saffron · 150ml stock", "method": "Simmer the chicken with the onion, lentils, fenugreek, ras el hanout and saffron in stock 45–60 min until the chicken is tender and the lentils are soft. Shred the msemen and layer it in a dish. Pile the chicken and lentils on top and ladle over the broth so the bread soaks it up.", "cookTime": "60–75 min", "kcal": "~410–480 kcal", "nutrition": "Protein 30g, Carbs 40g, high fibre", "storage": "Fridge 3 days; reheat with added stock.", "chefNotes": "Layer the shredded bread at the bottom to absorb the broth.", "pairsWith": "Alone as a complete meal.", "trivia": "Traditionally made for new mothers as a postpartum recovery dish.", "howThisFeels": "Shredded msemen, lentils and fragrant chicken — the dish made to welcome a new mother.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-sellou", "name": "Sellou", "nameAlt": "Almond Sesame Sweet", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["ramadan"], "ingredients": "40g roasted flour · 30g ground almonds · 20g sesame seeds (toasted) · 15g butter · 15g honey · 3g anise, cinnamon · icing sugar (dusting)", "method": "Toast the flour until golden, then mix with the ground almonds, toasted sesame, anise and cinnamon. Stir in the melted butter (or smen) and honey until it holds together in a sandy, clumping texture. Press into a dish or mound and dust with icing sugar.", "cookTime": "30–40 min", "kcal": "~260–310 kcal", "nutrition": "Fat 18g, Carbs 25g, high energy", "storage": "Airtight, 2–3 weeks.", "chefNotes": "Mix to a sandy texture, then press into shape. Use smen (aged butter) instead of butter for a traditional tang.", "pairsWith": "Mint tea.", "trivia": "A high-energy \"power food\" given to nursing mothers and eaten during Ramadan.", "howThisFeels": "Toasted, nutty and dense with energy — the sweet power-food kept ready for Ramadan.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-mrouzia", "name": "Mrouzia", "nameAlt": "Honey Lamb Tagine", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": ["eid", "celebration"], "ingredients": "180g lamb shoulder (cubed) · 50g raisins · 30g blanched almonds · 60g onion · 5g garlic · 5g ras el hanout · pinch saffron · 20ml olive oil · 25g honey · 100ml water · cinnamon stick", "method": "Brown the lamb, then soften the onion and garlic with the ras el hanout, saffron and cinnamon stick. Add the lamb and water/stock and simmer 60–80 min until very tender. Stir in the raisins and honey and reduce until the sauce is thick and glossy. Scatter with toasted almonds.", "cookTime": "70–90 min", "kcal": "~450–520 kcal", "nutrition": "Protein 32g, Fat 26g, Carbs 28g, high in iron", "storage": "Fridge 3–4 days; flavours develop, reheat slowly.", "chefNotes": "Balance the sweetness with the spices; cook until thick and glossy.", "pairsWith": "Couscous or flatbread.", "trivia": "Named after the Marinid dynasty; a luxurious dish for Eid al-Adha.", "howThisFeels": "Honeyed lamb, raisins and almonds — a dish fit for a dynasty and saved for Eid.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-briouats", "name": "Briouats", "nameAlt": "Savoury Pastries", "aliases": [], "course": "starter", "type": ["starter"], "diet": [], "cuisine": "north-africa", "country": "Morocco", "occasion": ["ramadan", "celebration"], "ingredients": "60g minced beef (filling) · 30g onion · 5g parsley · 5g spices (cumin, cinnamon) · 50g phyllo pastry · 15ml frying oil · egg yolk (sealing)", "method": "Cook the minced meat or shrimp with the onion, herbs and spices until dry; cool. Wrap spoonfuls in strips of phyllo or warqa, folding into triangles and sealing with egg yolk. Deep-fry until golden and crisp; drain.", "cookTime": "30–40 min", "kcal": "~290–350 kcal", "nutrition": "Protein 15g, Fat 18g, Carbs 25g", "storage": "Best fresh; fridge 2 days. Reheat in the oven to crisp up.", "chefNotes": "Use warqa dough for authenticity; fry until golden. A shrimp filling works in place of the meat.", "pairsWith": "Harissa or mint tea.", "trivia": "Popular at weddings and Ramadan; sweet almond-paste versions also exist.", "howThisFeels": "Crisp little pastry cigars, savoury or sweet — the bite that signals a celebration.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-moroccan-carrot-salad", "name": "Moroccan Carrot Salad", "nameAlt": "Cumin-Lemon Carrots", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["everyday"], "ingredients": "150g carrots (sliced) · 10ml olive oil · 5g garlic · 5g cumin, paprika · 10ml orange juice · 5ml lemon juice · parsley · salt, chilli flakes", "method": "Boil or steam the sliced carrots until just tender. Toss while warm with the olive oil, garlic, cumin, paprika, citrus juice, salt and chilli. Stir through the parsley and chill. Serve cold as a mezze.", "cookTime": "15–25 min", "kcal": "~120–160 kcal", "nutrition": "Carbs 18g, Fat 8g, high in vitamin A", "storage": "Fridge 4 days; serve cold as a mezze.", "chefNotes": "Cook the carrots tender but not mushy.", "pairsWith": "Tagines and grilled meats.", "trivia": "One of the most common daily salads — Morocco loves a cooked-vegetable mezze.", "howThisFeels": "Cumin-spiced, garlicky and bright — the cooked carrot salad Morocco eats most days.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-baghrir", "name": "Baghrir", "nameAlt": "Honeycomb Pancakes", "aliases": [], "course": "side", "type": ["side", "breakfast"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["breakfast"], "ingredients": "60g fine semolina · 30g flour · 3g yeast · 180ml warm water · pinch salt · honey, butter (serving)", "method": "Blend the semolina, flour, yeast, water and salt into a smooth, pourable batter and rest 1 hr until bubbly. Pour rounds onto a hot dry pan and cook on one side only, until the surface fills with holes and sets. Serve with melted butter and honey.", "cookTime": "25–35 min (batter rests 1 hr)", "kcal": "~240–290 kcal", "nutrition": "Carbs 48g, some protein", "storage": "Best fresh.", "chefNotes": "Cook one side only so the holes form on top.", "pairsWith": "Melted butter and honey.", "trivia": "The \"thousand holes\" pancakes — a favourite breakfast across Morocco.", "howThisFeels": "A thousand tiny holes drinking up butter and honey — the breakfast pancake everyone reaches for.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-seffa", "name": "Seffa", "nameAlt": "Sweet Couscous", "aliases": [], "course": "dessert", "type": ["dessert", "main"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["celebration"], "ingredients": "80g fine couscous · 30g raisins · 30g mixed nuts (almonds, walnuts) · 15g butter · 10g icing sugar · 2g cinnamon · orange blossom water", "method": "Steam the fine couscous (or cook the vermicelli) and toss with butter. Mix in the raisins and a little orange blossom water. Mound up, dust with icing sugar and cinnamon, and stud with the mixed nuts.", "cookTime": "30–40 min", "kcal": "~380–440 kcal", "nutrition": "Carbs 55g, Fat 16g, Protein 8g", "storage": "Best fresh.", "chefNotes": "Steam the couscous and toss through plenty of butter. Fine vermicelli works in place of couscous.", "pairsWith": "As a festive dish.", "trivia": "Served at weddings and births — the sweet version marks celebrations.", "howThisFeels": "Sweet couscous with cinnamon and nuts — the gentle finish that marks a wedding or a birth.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-grilled-sardines", "name": "Grilled Sardines", "nameAlt": "Charcoal-Grilled Sardines", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": ["everyday"], "ingredients": "180g fresh sardines (cleaned) · 10ml olive oil · 3g garlic · 2g parsley · 5g cumin, paprika · lemon juice · salt, chilli", "method": "Mix the olive oil, garlic, parsley, cumin, paprika, lemon, salt and chilli into a chermoula. Coat the cleaned sardines and leave 15–20 min. Grill over charcoal or a hot grill 3–4 min a side until charred and just cooked.", "cookTime": "15–20 min", "kcal": "~280–340 kcal", "nutrition": "Protein 30g, Fat 18g, high omega-3", "storage": "Best fresh.", "chefNotes": "Grill over charcoal for the best flavour.", "pairsWith": "Tomato salad and bread.", "trivia": "Abundant along the Atlantic coast — a simple, healthy everyday dish in cities like Essaouira.", "howThisFeels": "Charcoal smoke and sea salt off the Essaouira docks; you can almost hear the gulls.", "servings": 1, "sharedWith": ""},
  {"id": "morocco-amlou", "name": "Amlou", "nameAlt": "Almond Argan Spread", "aliases": [], "course": "side", "type": ["side", "breakfast"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Morocco", "occasion": [], "ingredients": "40g toasted almonds (ground) · 15ml argan oil · 10g honey · pinch salt", "method": "Toast the almonds and grind them coarsely. Blend or stir in the argan oil and honey with a pinch of salt until it forms a thick, spreadable paste. Store in a jar; serve with msemen or bread.", "cookTime": "15–20 min (no-cook mix)", "kcal": "~220–260 kcal", "nutrition": "Fat 20g, Protein 6g, vitamin E rich", "storage": "Airtight jar, up to 2 weeks.", "chefNotes": "Grind the almonds coarsely for texture.", "pairsWith": "Msemen or bread.", "trivia": "Unique to southwestern Morocco; argan oil is \"liquid gold\" and UNESCO-protected.", "howThisFeels": "Toasted almonds and 'liquid gold' argan oil — a spoon of the Souss valley on warm bread.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-thieboudienne", "name": "Thieboudienne", "nameAlt": "Fish & Rice", "aliases": ["Ceebu Jen"], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": [], "ingredients": "150g firm white fish (grouper/snapper) · 80g broken long-grain rice · 80g tomatoes (blended) · 30g tomato paste · 50g onion · 3g garlic · 2g ginger · 100g mixed veg (carrot, eggplant, cabbage, okra, cassava) · 15ml veg oil · 200ml fish stock · chilli, salt, bay", "method": "Make a nokoss paste of garlic, ginger, parsley and chilli and stuff it into slits in the fish. Fry the fish briefly and set aside. In the oil, fry the onion and tomato paste, add the blended tomato and cook down. Add the stock and the firmer vegetables and simmer until tender, returning the fish to finish. Lift everything out, then cook the broken rice in the same sauce until tender. Serve the rice topped with the fish and vegetables.", "cookTime": "60–75 min", "kcal": "~420–490 kcal", "nutrition": "Carbs 55g, Protein 28g, Fat 14g; rich in veg vitamins", "storage": "Fridge 3 days; flavours deepen, reheat with a splash of water.", "chefNotes": "Use broken rice for authentic texture; layer the ingredients carefully. Palm oil instead of veg oil gives the more traditional colour and flavour.", "pairsWith": "Lime wedges, fresh salad.", "trivia": "Invented in Saint-Louis in the 19th century; UNESCO-recognised heritage, eaten communally from one bowl.", "howThisFeels": "Fish, broken rice and slow vegetables from one shared bowl — Senegal's pride, eaten elbow to elbow.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-yassa-ganaar", "name": "Yassa Ganaar", "nameAlt": "Chicken Yassa", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": [], "ingredients": "200g chicken pieces · 150g onions (sliced) · 30ml lemon juice · 15ml mustard · 10ml veg oil · 5g garlic · 5g chilli · salt, pepper, bay", "method": "Marinate the chicken in the lemon juice, mustard, sliced onions, garlic, chilli and seasoning at least 2 hrs (overnight is best). Grill or sear the chicken, then set aside. Cook the marinade onions slowly in oil until soft and caramelised, return the chicken with a little water, and simmer 30–40 min until tender and saucy.", "cookTime": "50–70 min (marinate 2 hrs+)", "kcal": "~380–450 kcal", "nutrition": "Protein 35g, Fat 20g, Carbs 12g", "storage": "Fridge 3–4 days; great cold in sandwiches.", "chefNotes": "Caramelise the onions slowly for sweetness.", "pairsWith": "White rice or couscous.", "trivia": "From the Casamance region — a classic Senegalese-French fusion.", "howThisFeels": "Lemon, mustard and a mountain of caramelised onions — Casamance tang that lingers on your fingers.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-mafe", "name": "Mafe", "nameAlt": "Peanut Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": [], "ingredients": "150g beef · 40g natural peanut butter · 50g tomatoes (blended) · 50g onion · 100g mixed veg (potato, carrot, cabbage) · 10ml oil · 150ml stock · chilli, salt, garlic, ginger", "method": "Brown the meat in oil, then set aside. Fry the onion, add the blended tomatoes and cook down. Return the meat with the stock and simmer 20 min. Add the vegetables and cook until tender. Whisk the peanut butter with a little liquid and stir in for the last 10–15 min until rich; don't let it catch. Season.", "cookTime": "45–60 min", "kcal": "~420–480 kcal", "nutrition": "Protein 28g, Fat 25g, Carbs 18g", "storage": "Fridge 3–4 days; freezes well. Reheats beautifully; thin if thickened.", "chefNotes": "Stir the peanut butter in at the end to prevent burning. Chicken works in place of beef.", "pairsWith": "Rice or couscous.", "trivia": "Also called Domoda; peanuts are Senegal's main cash crop.", "howThisFeels": "Deep, nutty and slow; the peanut stew that makes a whole kitchen smell like somewhere worth lingering.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-ndambe", "name": "Ndambé", "nameAlt": "Black-Eyed Pea Stew", "aliases": [], "course": "main", "type": ["main", "breakfast"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": ["breakfast", "street-food"], "ingredients": "80g black-eyed peas (soaked & cooked) · 30g tomatoes · 20g onion (blended) · 10ml veg oil · 3g garlic · 2g chilli · salt, bouillon · 60g bread roll (to serve)", "method": "Soak and cook the black-eyed peas until soft, then mash slightly. Fry the blended tomato and onion in the oil with the chilli and garlic. Stir in the peas with a little water and bouillon and simmer 15 min until thick. Serve spooned into bread rolls.", "cookTime": "40–50 min (after soaking)", "kcal": "~280–340 kcal", "nutrition": "Protein 15g, Carbs 40g, high fibre", "storage": "Fridge 4 days.", "chefNotes": "Cook the peas until soft, then mash slightly. Palm oil gives the traditional colour; veg oil works fine.", "pairsWith": "Bread, or as a side to rice.", "trivia": "A popular, affordable street breakfast.", "howThisFeels": "Soft black-eyed peas spooned into a roll — Dakar's affordable, filling morning.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-thiakry", "name": "Thiakry", "nameAlt": "Couscous Pudding", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": ["ramadan", "celebration"], "ingredients": "50g millet couscous (cooked) · 100ml yogurt · 15g sugar · 50g raisins · vanilla (optional)", "method": "Steam or cook the millet couscous and fluff. While still warm, stir in the yogurt (or sour milk), sugar and vanilla, then fold in the raisins or pineapple. Chill before serving.", "cookTime": "20–30 min + chilling", "kcal": "~220–280 kcal", "nutrition": "Carbs 35g, Protein 8g, Fat 6g", "storage": "Fridge 3 days.", "chefNotes": "Mix while warm for the best absorption. Sour milk works in place of yogurt; use pineapple instead of raisins, and a little coconut if you like.", "pairsWith": "After spicy mains.", "trivia": "A refreshing dessert popular during Ramadan and celebrations.", "howThisFeels": "Cool, sweet and gently spiced, the soft landing after a fiery plate.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-bissap", "name": "Bissap", "nameAlt": "Hibiscus Drink", "aliases": [], "course": "drink", "type": ["drink"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": [], "ingredients": "20g dried hibiscus flowers · 300ml water · 20g sugar · 5g mint · orange blossom (optional) · ice", "method": "Rinse the dried hibiscus and simmer in the water 10–15 min. Stir in the sugar and mint (and orange blossom if using). Strain, cool, then chill. Serve very cold over ice.", "cookTime": "15–20 min + cooling", "kcal": "~80–110 kcal", "nutrition": "low calorie, high in vitamin C and antioxidants", "storage": "Fridge 4–5 days.", "chefNotes": "Adjust the sweetness; serve very cold.", "pairsWith": "Any meal, or as refreshment.", "trivia": "Senegal's most popular drink (\"jus de bissap\") — deep red and tart.", "howThisFeels": "Tart, ruby-red and ice-cold — the first sip tastes like shade on a hot Dakar afternoon.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-dibi", "name": "Dibi", "nameAlt": "Grilled Meat", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": ["street-food"], "ingredients": "180g lamb · 10ml oil · 5g mustard · 20g onion · salt, pepper, chilli · onion relish (to serve)", "method": "Rub the meat with the mustard-onion marinade, oil, salt, pepper and chilli; leave 30 min+. Grill over charcoal until charred and just cooked. Serve with a raw onion relish, mustard and bread.", "cookTime": "20–30 min (after marinating)", "kcal": "~380–450 kcal", "nutrition": "Protein 35g, Fat 22g", "storage": "Best fresh.", "chefNotes": "Grill over charcoal for a smoky flavour. Beef works in place of lamb.", "pairsWith": "Bread, mustard, onions.", "trivia": "Iconic street food; \"dibi\" means grilled meat in Wolof.", "howThisFeels": "Charred meat, raw onions and mustard wrapped in bread — Wolof for 'grilled', and for good company.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-fataya", "name": "Fataya", "nameAlt": "Fish Pastries", "aliases": [], "course": "starter", "type": ["starter"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": ["street-food"], "ingredients": "80g white fish (minced) · 50g onion · 3g garlic · 2g parsley · 5g chilli · 60g pastry dough (or spring roll wrappers) · 15ml frying oil (absorbed) · salt, pepper, lemon", "method": "Fry the onion, add the minced fish with garlic, parsley and chilli, season with salt, pepper and lemon, and cook until dry. Cool. Spoon onto pastry rounds, fold into half-moons and seal the edges. Deep-fry in batches until golden and crisp.", "cookTime": "30–40 min", "kcal": "~280–340 kcal", "nutrition": "Protein 18g, Fat 15g, Carbs 22g", "storage": "Best fresh; fridge 2 days. Reheat in the oven to re-crisp.", "chefNotes": "Seal the edges well to prevent leaking; fry in batches.", "pairsWith": "Tomato-onion sauce, or as a party appetiser.", "trivia": "A coastal street food, similar to empanadas — Portuguese and French influence.", "howThisFeels": "Crisp half-moons of spiced fish — the coastal pastry that vanishes at every party.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-accara", "name": "Accara", "nameAlt": "Black-Eyed Pea Fritters", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": ["breakfast", "street-food"], "ingredients": "60g black-eyed peas (soaked & peeled) · 20g onion · 5g chilli · 5g garlic · salt · 15ml frying oil (absorbed)", "method": "Soak and peel the black-eyed peas, then blend with the onion, chilli and garlic into a thick batter; whisk well for fluffiness and season. Drop spoonfuls into hot oil and fry until golden; drain.", "cookTime": "25–35 min (after soaking overnight)", "kcal": "~240–300 kcal", "nutrition": "Protein 12g, Carbs 25g, high fibre", "storage": "Best fresh.", "chefNotes": "Blend into a thick batter; whisk for fluffiness.", "pairsWith": "Bread or a bissap drink.", "trivia": "A cheap, protein-rich street breakfast across Senegal.", "howThisFeels": "Fluffy fried bean fritters, hot and golden — the protein-packed breakfast off a street corner.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-soupou-kanja", "name": "Soupou Kanja", "nameAlt": "Okra Stew", "aliases": ["Supa Kanja"], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": [], "ingredients": "60g beef · 60g white fish · 40g prawns · 150g fresh okra (sliced) · 20ml palm oil · 50g onion · 3g garlic · 2g ginger · 30g smoked fish · 100ml stock · chilli, salt", "method": "Fry the onion in palm oil, add the meat and brown. Add the stock, smoked fish and ginger/garlic and simmer until the meat is tender. Stir in the sliced okra and the seafood and simmer 10–15 min, stirring for the natural thickening. Season with chilli and salt.", "cookTime": "45–60 min", "kcal": "~320–400 kcal", "nutrition": "Protein 25g, Fat 18g, high fibre & vitamins", "storage": "Fridge 3 days; add water if too thick when reheating.", "chefNotes": "Slice the okra thinly for natural thickening.", "pairsWith": "Rice or couscous.", "trivia": "Also popular in Gambia; the okra gives the prized viscous texture.", "howThisFeels": "Okra-thick and brimming with seafood — the glossy stew shared from Senegal to the Gambia.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-thiebou-yapp", "name": "Thiébou Yapp", "nameAlt": "Meat & Rice", "aliases": ["Ceebu Yapp"], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": ["celebration"], "ingredients": "150g beef (stewing) · 80g broken rice · 80g tomatoes (blended) · 40g tomato paste · 50g onion · 100g mixed veg (carrot, cabbage, eggplant) · 15ml oil · 200ml stock · garlic, chilli, bay", "method": "Brown the meat well in oil, then set aside. Fry the onion and tomato paste, add the blended tomato and cook down. Return the meat with the stock and the firmer vegetables and simmer until tender. Lift out the meat and veg, cook the broken rice in the sauce until tender, and serve topped with the meat and vegetables.", "cookTime": "55–70 min", "kcal": "~430–500 kcal", "nutrition": "Carbs 55g, Protein 28g, Fat 15g", "storage": "Fridge 3–4 days; excellent reheated or fried.", "chefNotes": "Brown the meat well for depth. Lamb works in place of beef.", "pairsWith": "Fresh salad or pickles.", "trivia": "The meat-focused counterpart to Thieboudienne; popular at celebrations.", "howThisFeels": "Meat and rich red rice for the meat-lovers — Thieboudienne's celebratory cousin.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-pastels", "name": "Pastels", "nameAlt": "Fried Pastries", "aliases": [], "course": "starter", "type": ["starter"], "diet": [], "cuisine": "west-africa", "country": "Senegal", "occasion": ["celebration", "street-food"], "ingredients": "60g white fish (minced) · 30g onion · 5g garlic · 5g chilli · 60g pastry dough · 15ml frying oil (absorbed)", "method": "Fry the onion with garlic and chilli, add the minced fish or beef and cook until dry; season and cool. Roll the dough thin, cut rounds, fill, fold into pockets and seal. Deep-fry until golden; drain on paper.", "cookTime": "30–40 min", "kcal": "~260–320 kcal", "nutrition": "Protein 15g, Fat 14g, Carbs 25g", "storage": "Best fresh.", "chefNotes": "Fry until golden and drain well. Minced beef works in place of fish.", "pairsWith": "A spicy dipping sauce.", "trivia": "A popular party and street snack throughout Senegal.", "howThisFeels": "Golden fried pockets of fish or beef — the party snack passed hand to hand.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-lakh", "name": "Lakh", "nameAlt": "Sweet Millet Pudding", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": ["ramadan", "celebration"], "ingredients": "50g millet couscous · 100ml yogurt · 20g sugar · 30g raisins · orange blossom water (optional)", "method": "Steam the millet couscous lightly and fluff. While warm, mix in the yogurt (or sour milk) and sugar, then fold in the raisins or dates and a little orange blossom or coconut. Chill before serving.", "cookTime": "20–30 min + chilling", "kcal": "~210–260 kcal", "nutrition": "Carbs 38g, Protein 7g", "storage": "Fridge 3 days.", "chefNotes": "Steam the couscous lightly before mixing. Sour milk works in place of yogurt; dates instead of raisins, with a little coconut if you like.", "pairsWith": "After heavy stews.", "trivia": "A festive dessert, often served during Ramadan or family gatherings.", "howThisFeels": "Sweet millet and cool sour milk — the festive pudding that lands during Ramadan.", "servings": 1, "sharedWith": ""},
  {"id": "senegal-cafe-touba", "name": "Café Touba", "nameAlt": "Spiced Coffee", "aliases": [], "course": "drink", "type": ["drink"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Senegal", "occasion": ["everyday"], "ingredients": "8g ground coffee · 2g cloves · 200ml hot water · 10g sugar (to taste)", "method": "Boil the water and add the ground coffee blended with the cloves (or Guinea pepper). Steep or boil a few minutes for a strong, spicy brew, then strain. Sweeten to taste and serve hot.", "cookTime": "10–15 min", "kcal": "~50–80 kcal (with sugar)", "nutrition": "antioxidants, low calorie without sugar", "storage": "Best fresh.", "chefNotes": "Boil the spices with the coffee for a strong flavour. Guinea pepper (grains of selim) instead of cloves is the traditional kick.", "pairsWith": "Breakfast, or as a pick-me-up.", "trivia": "Named after the holy city of Touba; a daily ritual drink with a spicy kick.", "howThisFeels": "Coffee spiced with clove and pepper — the holy-city brew that starts a Senegalese day.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-pilau", "name": "Pilau", "nameAlt": "Spiced Rice", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Tanzania", "occasion": [], "ingredients": "80g basmati rice · 120g beef · 50g onion · 3g garlic · 2g ginger · 6g pilau masala (cardamom, cinnamon, cloves) · 10ml veg oil · 150ml stock · salt", "method": "Fry the pilau masala in oil with the onion, garlic and ginger until fragrant and golden. Brown the meat, add the rice and toss to coat, then pour in the stock. Bring to a boil, cover and cook on low 18–20 min until absorbed. Rest and fluff.", "cookTime": "45–55 min", "kcal": "~430–490 kcal", "nutrition": "Protein 24g, Carbs 50g, Fat 16g", "storage": "Fridge 3 days; fry next day for crispy pilau.", "chefNotes": "Fry the spices first to release the full aroma. Chicken works in place of beef.", "pairsWith": "Kachumbari and mango pickle.", "trivia": "Influenced by Indian, Arab and Persian traders along the Zanzibar coast.", "howThisFeels": "Rice perfumed with cardamom, clove and cinnamon — the spice routes of Zanzibar in one pot.", "servings": 1, "sharedWith": "Kenya"},
  {"id": "tanzania-zanzibar-biryani", "name": "Zanzibar Biryani", "nameAlt": "Spiced Layered Rice", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["celebration"], "ingredients": "80g basmati rice · 120g chicken · 60g potatoes · 50g onion · 8g biryani masala · 10ml ghee · 5g turmeric · 150ml stock", "method": "Marinate the meat in the biryani masala. Parboil the rice. Fry the onions golden, brown the meat in the masala with stock until tender, and fry the potatoes. Layer the rice, meat and potatoes with the saffron, cover tightly, and steam on low (dum) 30–40 min. Rest and fold gently.", "cookTime": "55–70 min", "kcal": "~460–530 kcal", "nutrition": "Protein 26g, Carbs 55g, Fat 18g", "storage": "Fridge 3 days; reheat with a little milk or water.", "chefNotes": "Layer and steam on low (\"dum\" style). Chicken or beef both work; oil instead of ghee is fine; a pinch of soaked saffron in place of turmeric for a more luxurious colour.", "pairsWith": "Cucumber raita and mango chutney.", "trivia": "A festive Swahili dish reflecting Zanzibar's rich trading history.", "howThisFeels": "Layered, fragrant and festive — a plate carrying centuries of Indian Ocean trade.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-vitumbua", "name": "Vitumbua", "nameAlt": "Coconut Rice Cakes", "aliases": [], "course": "dessert", "type": ["dessert", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["ramadan", "breakfast", "street-food"], "ingredients": "60g rice flour · 40ml coconut milk · 15g sugar · 3g yeast · 3g cardamom · 10ml frying oil (absorbed)", "method": "Blend the rice flour with the coconut milk, sugar, yeast and cardamom into a thick batter; leave to ferment slightly. Heat an oiled mould pan, spoon in the batter, and cook until set and golden underneath, flipping to colour the tops.", "cookTime": "30–40 min", "kcal": "~240–300 kcal", "nutrition": "Carbs 42g, Fat 10g", "storage": "Best fresh; airtight 1–2 days.", "chefNotes": "Ferment the batter slightly and fry in small moulds.", "pairsWith": "Hot chai or ginger tea.", "trivia": "A beloved coastal street food, big during Ramadan and morning markets.", "howThisFeels": "Little coconut rice cakes, crisp-edged and soft-centred — the morning-market sweet of the coast.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-samaki-wa-kupaka", "name": "Samaki wa Kupaka", "nameAlt": "Coconut Fish", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": [], "ingredients": "180g firm white fish (kingfish/snapper) · 120ml coconut milk · 50g onion · 3g garlic · 2g ginger · 8g tamarind paste · 5g turmeric, chilli · 10ml veg oil · salt", "method": "Grill or fry the fish until almost done. Make a sauce by simmering the onion, garlic, ginger, turmeric, chilli, tamarind and coconut milk until thick. Coat the fish in the sauce and simmer gently a few minutes to finish. Season.", "cookTime": "30–40 min", "kcal": "~360–430 kcal", "nutrition": "Protein 32g, Fat 24g, Carbs 10g", "storage": "Fridge 2 days; reheat gently, excellent with rice.", "chefNotes": "Finish the fish in the coconut sauce to keep it tender. Lemon juice works in place of tamarind paste.", "pairsWith": "Coconut rice or ugali.", "trivia": "A hallmark of Zanzibari cuisine, from Indian Ocean trade.", "howThisFeels": "Grilled fish blanketed in coconut sauce — Zanzibar's gift from the spice islands.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-mishkaki", "name": "Mishkaki", "nameAlt": "Grilled Skewers", "aliases": [], "course": "main", "type": ["main", "snack"], "diet": [], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["street-food"], "ingredients": "160g beef (cubed) · 10ml yogurt · 3g garlic · 2g ginger · 5g chilli powder, cumin · 3g salt · lemon wedges", "method": "Marinate the cubed meat in the yogurt/oil, garlic, ginger, chilli, cumin and salt (overnight for events). Thread onto skewers and grill over charcoal 10–15 min, turning, until charred and just cooked. Serve with lemon.", "cookTime": "20–30 min", "kcal": "~340–410 kcal", "nutrition": "Protein 34g, Fat 20g", "storage": "Fridge 3 days; great cold in salads or wraps.", "chefNotes": "Grill over charcoal for the smoky flavour. Chicken works in place of beef; oil instead of yogurt for the marinade.", "pairsWith": "Kachumbari and pilau.", "trivia": "One of the most loved evening street foods in Dar es Salaam.", "howThisFeels": "Skewers smoking over coals at dusk — Dar es Salaam's favourite evening ritual.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-maharage-ya-nazi", "name": "Maharage ya Nazi", "nameAlt": "Beans in Coconut", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["everyday"], "ingredients": "80g red kidney beans (soaked & cooked) · 100ml coconut milk · 50g onion · 5g garlic · 5g curry powder · 10ml veg oil · salt, chilli", "method": "Soak and cook the kidney beans until soft. Fry the onion and garlic, add the curry powder, then the beans and coconut milk. Simmer gently 15–20 min until the sauce thickens. Season with salt and chilli.", "cookTime": "35–45 min (after soaking)", "kcal": "~280–340 kcal", "nutrition": "Protein 12g, Fat 16g, Carbs 32g, high fibre", "storage": "Fridge 4 days; mash and serve as a spread.", "chefNotes": "Simmer gently to thicken the coconut sauce.", "pairsWith": "Ugali or rice.", "trivia": "A simple, nutritious everyday dish, coastal and inland alike.", "howThisFeels": "Beans simmered creamy in coconut milk — the gentle everyday pot, coast to highland.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-kisamvu", "name": "Kisamvu", "nameAlt": "Cassava Leaves Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": [], "ingredients": "200g cassava leaves (finely pounded) · 30g peanut butter · 50g onion · 5g garlic · 10ml oil · salt, chilli", "method": "Finely pound or grind the cassava leaves. Boil until tender, then sauté with the onion and garlic. Stir in the peanut butter or coconut milk and simmer 15–20 min until thick. Season with salt and chilli.", "cookTime": "40–50 min", "kcal": "~220–290 kcal", "nutrition": "Protein 10g, Fat 14g, Carbs 18g; very high in vitamin A", "storage": "Fridge 3 days; reheat with extra liquid.", "chefNotes": "Pound the leaves thoroughly, or use frozen for convenience. Coconut milk instead of peanut butter for a coastal version.", "pairsWith": "Ugali and grilled fish.", "trivia": "A traditional, nutrient-dense dish from rural Tanzania.", "howThisFeels": "Pounded cassava leaves rich with peanut — green, dense and deeply nourishing.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-mtori", "name": "Mtori", "nameAlt": "Banana Soup", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "east-africa", "country": "Tanzania", "occasion": [], "ingredients": "150g green plantains (mashed) · 100g stewing beef (chuck or shin) · 50g onion · 3g garlic · 2g ginger · 10ml oil · 200ml beef stock · salt, pepper", "method": "Simmer the beef with the onion, garlic and ginger in stock until tender. Add the peeled green plantains and cook until very soft. Mash the plantains into the broth (or blend part of it) for a thick, creamy soup. Season.", "cookTime": "50–65 min", "kcal": "~340–410 kcal", "nutrition": "Protein 24g, Carbs 45g, Fat 12g", "storage": "Fridge 3 days; reheat and mash further if you like.", "chefNotes": "Mash the plantains into the soup for a thick, comforting texture.", "pairsWith": "Ugali.", "trivia": "A warming highland dish from the Chagga people near Mount Kilimanjaro.", "howThisFeels": "Green bananas and beef cooked to a soup — a warm hug from the slopes of Kilimanjaro.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-halwa", "name": "Halwa", "nameAlt": "Semolina Sweet", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["eid"], "ingredients": "40g semolina · 30g sugar · 20g ghee · 30g mixed nuts (cashews, pistachios) · 5g cardamom · 80ml water", "method": "Toast the semolina in ghee until golden. Make a sugar syrup with the water and cardamom, then whisk in the semolina, stirring constantly until thick, glossy and pulling from the pan. Fold in the nuts, press into a tray and cool. Cut into pieces.", "cookTime": "25–35 min", "kcal": "~280–340 kcal", "nutrition": "Carbs 38g, Fat 16g", "storage": "Airtight, up to 1 week.", "chefNotes": "Stir constantly for a smooth, glossy texture. Butter works in place of ghee.", "pairsWith": "Black tea, or after spicy meals.", "trivia": "Popular during Eid, showing strong Swahili and Arab influence.", "howThisFeels": "Glossy, chewy and nut-studded — the Eid sweet that glints with Swahili-Arab heritage.", "servings": 1, "sharedWith": ""},
  {"id": "tanzania-tanzanian-chai", "name": "Tanzanian Chai", "nameAlt": "Spiced Milk Tea", "aliases": [], "course": "drink", "type": ["drink"], "diet": ["vegetarian"], "cuisine": "east-africa", "country": "Tanzania", "occasion": ["everyday"], "ingredients": "120ml milk · 80ml water · 5g loose black tea · 10g sugar · 3g fresh ginger · 2g cardamom pods · pinch cinnamon", "method": "Bring the milk-and-water with the ginger, cardamom and cinnamon to a simmer. Add the black tea and sugar and simmer a few minutes until well-coloured and fragrant. Strain and serve hot.", "cookTime": "10–15 min", "kcal": "~90–120 kcal", "nutrition": "Protein 4g, Carbs 12g", "storage": "Best fresh.", "chefNotes": "Boil the spices with the tea and milk for the full flavour.", "pairsWith": "Vitumbua, mahamri, or mandazi.", "trivia": "Drinking chai is a central social activity in Tanzania, enjoyed several times a day.", "howThisFeels": "Milky, spiced and shared several times a day — the cup that pauses the clock.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-couscous-tunisien", "name": "Couscous Tunisien", "nameAlt": "Tunisian Couscous", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Tunisia", "occasion": [], "ingredients": "80g dry couscous · 150g lamb · 100g mixed veg (zucchini, carrot, pumpkin, chickpeas) · 50g onion · 10ml olive oil · 5g harissa · 5g ras el hanout · 150ml stock · coriander", "method": "Brown the meat, then soften the onion and stir in the harissa and ras el hanout. Add the stock and the firmer vegetables and chickpeas and simmer until tender. Steam the couscous in stages, fluffing with oil. Mound the couscous, top with the meat and vegetables, and ladle over the spicy broth. Finish with coriander.", "cookTime": "55–70 min", "kcal": "~410–480 kcal", "nutrition": "Carbs 52g, Protein 28g, Fat 16g, high fibre", "storage": "Fridge 3 days. Re-steam couscous with a little water.", "chefNotes": "Add the harissa gradually for your heat level; keep the vegetables chunky. Chicken works in place of lamb.", "pairsWith": "Buttermilk or extra harissa.", "trivia": "Every region has its version; often a Friday family dish.", "howThisFeels": "Fiery, tomato-red and piled high — every region's Friday, ladled over fluffy grains.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-brik-a-l-oeuf", "name": "Brik à l'Oeuf", "nameAlt": "Egg & Tuna Pastry", "aliases": [], "course": "starter", "type": ["starter"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["ramadan", "street-food"], "ingredients": "50g phyllo pastry · 1 egg · 40g canned tuna · 20g onion · 5g parsley · 5g harissa · 15ml frying oil · salt, pepper", "method": "Mix the tuna with the onion, parsley and harissa. Lay out a pastry sheet, spoon the tuna into the centre, crack a whole egg on top, and fold into a triangle, sealing the edges. Slide into hot oil and fry quickly until golden and crisp, keeping the yolk runny. Drain; serve with lemon.", "cookTime": "20–30 min", "kcal": "~320–380 kcal", "nutrition": "Protein 18g, Fat 20g, Carbs 22g", "storage": "Best fresh; reheat in the oven to re-crisp.", "chefNotes": "Fold into triangles, seal well, and fry quickly to keep the egg soft. Malsouka (brik pastry) is the traditional wrapper; phyllo is the easy stand-in.", "pairsWith": "Lemon wedges and harissa.", "trivia": "An iconic street food and Ramadan favourite — the runny egg takes skill.", "howThisFeels": "Shatter-crisp pastry hiding a runny egg — one bite and you've earned it.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-lablabi", "name": "Lablabi", "nameAlt": "Chickpea Soup", "aliases": [], "course": "main", "type": ["main", "breakfast"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["breakfast"], "ingredients": "80g chickpeas (soaked & cooked) · 50g bread (broken) · 10ml olive oil · 5g garlic · 5g harissa · 5g cumin · 200ml chickpea liquid · lemon, capers, tuna (optional)", "method": "Cook the chickpeas until very soft, keeping the cooking liquid. Tear the bread into a bowl. Mix the garlic, harissa, cumin and olive oil into the hot chickpea broth, mashing some chickpeas for body. Ladle over the bread and top with lemon, capers, egg or tuna as you like.", "cookTime": "25–35 min (after soaking)", "kcal": "~280–340 kcal", "nutrition": "Protein 14g, Carbs 42g, high fibre", "storage": "Fridge 3 days; reheat the broth and add fresh bread.", "chefNotes": "Mash some chickpeas for a creamier texture.", "pairsWith": "Topped with egg, tuna and harissa.", "trivia": "A cheap, endlessly customisable Tunis breakfast.", "howThisFeels": "Hot chickpeas over torn bread, dressed however you like — Tunis breakfast, endlessly your own.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-ojja", "name": "Ojja", "nameAlt": "Spicy Egg Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["everyday"], "ingredients": "2 eggs · 40g merguez · 80g tomatoes (blended) · 40g green peppers · 10ml olive oil · 8g harissa · 5g garlic · 3g cumin", "method": "Fry the garlic and green peppers in olive oil, add the harissa and cumin, then the blended tomato (and merguez if using). Simmer until thick. Make wells and crack in the eggs; cover and cook until just set. Serve with bread.", "cookTime": "25–35 min", "kcal": "~260–340 kcal", "nutrition": "Protein 18g, Fat 18g, Carbs 12g", "storage": "Fridge 2 days; reheat gently, add fresh eggs if needed.", "chefNotes": "Get the sauce thick first, then crack the eggs on top. Plain Ojja without merguez also works.", "pairsWith": "Bread for scooping.", "trivia": "Everyday spicy comfort food, popular for brunch.", "howThisFeels": "Eggs poached in spicy tomato and pepper — brunch with a chilli wake-up call.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-tunisian-tajine", "name": "Tunisian Tajine", "nameAlt": "Baked Omelette", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Tunisia", "occasion": [], "ingredients": "100g minced beef · 80g potatoes (cooked) · 2 eggs · 30g grated cheese · 30g onion · 10g parsley · 5g harissa · 10ml olive oil", "method": "Fry the onion and minced meat or chicken until cooked, then mix with the cooked diced potato, parsley and harissa. Beat the eggs with the grated cheese, stir everything together, and pour into an oiled baking dish. Bake at 180°C 30–40 min until set and golden. Cut into squares; serve hot or cold.", "cookTime": "35–45 min", "kcal": "~380–450 kcal", "nutrition": "Protein 28g, Fat 24g, Carbs 18g", "storage": "Fridge 3 days; excellent cold or reheated.", "chefNotes": "Mix everything and bake until set and golden. Chicken works in place of minced beef.", "pairsWith": "Salad and bread.", "trivia": "Completely different from a Moroccan tagine — more like a thick frittata.", "howThisFeels": "Nothing like its Moroccan namesake — a thick, baked egg-and-meat slab cut into squares.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-mloukhia", "name": "Mloukhia", "nameAlt": "Jute Leaf Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "north-africa", "country": "Tunisia", "occasion": [], "ingredients": "150g beef · 80g dried mloukhia powder · 10ml olive oil · 5g garlic · 5g coriander seeds · 200ml stock · harissa", "method": "Fry the garlic and crushed coriander seeds in olive oil until fragrant. Whisk in the mloukhia powder (or add fresh leaves) with the stock to a smooth, dark sauce. Add the browned meat and harissa, then simmer gently 60–80 min until the meat is tender and the sauce thickens.", "cookTime": "60–80 min", "kcal": "~340–410 kcal", "nutrition": "Protein 30g, Fat 18g, high iron", "storage": "Fridge 3–4 days; flavours intensify next day.", "chefNotes": "Fry the garlic and coriander first for the aroma. Lamb works in place of beef. Fresh mloukhia leaves work in place of the dried powder.", "pairsWith": "Rice or couscous.", "trivia": "A traditional winter dish — the dark green colour is unmistakable.", "howThisFeels": "Long-simmered to a deep, dark green — the winter stew whose colour you never forget.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-makroudh", "name": "Makroudh", "nameAlt": "Date-Filled Cookies", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["ramadan", "celebration"], "ingredients": "60g semolina · 30g butter · 40g date paste · 5g orange blossom water · 30ml honey (soaking) · frying oil", "method": "Make a semolina dough with the butter/oil and orange blossom water. Roll out, pipe or spread a strip of date paste down the centre, fold the dough over and cut into diamonds. Deep-fry until golden, then soak in warm honey. Drain.", "cookTime": "40–50 min", "kcal": "~320–380 kcal", "nutrition": "Carbs 48g, Fat 14g", "storage": "Airtight, up to 2 weeks.", "chefNotes": "Cut into diamonds and deep-fry until golden. Oil works in place of butter.", "pairsWith": "Mint tea.", "trivia": "A classic festive sweet, especially at Ramadan and holidays.", "howThisFeels": "Semolina folded around sticky dates and dipped in syrup — the festive bite of Ramadan.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-slata-mechouia", "name": "Slata Mechouia", "nameAlt": "Grilled Salad", "aliases": [], "course": "starter", "type": ["starter"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["celebration"], "ingredients": "100g tomatoes · 80g green peppers · 40g onion · 5g garlic (roasted) · 10ml olive oil · 5g harissa · lemon juice · salt, tuna flakes (optional, 20g)", "method": "Char the tomatoes, peppers, onion and garlic on a grill until blackened and soft, then peel and chop finely. Mix with the olive oil, harissa, lemon and salt. Top with tuna and egg if liked. Serve cold.", "cookTime": "25–35 min", "kcal": "~140–190 kcal", "nutrition": "Carbs 12g, Fat 10g, high in vitamin C & antioxidants", "storage": "Fridge 3–4 days; serve cold as a spread on bread.", "chefNotes": "Char the vegetables well for a smoky flavour, then chop roughly.", "pairsWith": "A mezze spread with brik and olives.", "trivia": "Called the \"Tunisian flag salad\" for its red and green — a must at gatherings.", "howThisFeels": "Grilled peppers and tomato chopped fine — red and green, the 'flag salad' of every gathering.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-kefteji", "name": "Kefteji", "nameAlt": "Mixed Vegetable Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["street-food", "everyday"], "ingredients": "150g potatoes (fried) · 40g green peppers · 40g zucchini · 2 eggs · 40g tomato sauce · 8g harissa · 10ml olive oil · 5g garlic · salt, cumin", "method": "Fry the potato cubes, peppers and zucchini until golden, then chop roughly. Simmer the tomato sauce with garlic, harissa and cumin, return the fried vegetables, and fry or scramble the eggs through. Serve with bread.", "cookTime": "35–45 min", "kcal": "~360–420 kcal", "nutrition": "Protein 18g, Carbs 35g, Fat 20g", "storage": "Fridge 3 days; reheat gently and add fresh eggs.", "chefNotes": "Fry the potatoes separately for a crisp texture.", "pairsWith": "Bread or couscous.", "trivia": "A beloved everyday comfort dish, big at street stalls.", "howThisFeels": "Fried vegetables and egg chopped together — the comforting jumble of a Tunisian street stall.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-chorba", "name": "Chorba", "nameAlt": "Tunisian Soup", "aliases": [], "course": "main", "type": ["main", "starter"], "diet": [], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["ramadan"], "ingredients": "100g stewing lamb (shoulder or neck) · 30g orzo pasta · 60g tomatoes (blended) · 30g onion · 10g celery · 5g garlic · 5g harissa · coriander, caraway · 10ml olive oil · 250ml stock · coriander", "method": "Brown the lamb, then soften the onion and celery with the garlic, harissa and spices. Add the blended tomato and stock and simmer 40 min. Add the orzo and cook until the pasta is tender and the soup is rich. Finish with coriander and lemon.", "cookTime": "50–65 min", "kcal": "~320–380 kcal", "nutrition": "Protein 22g, Carbs 28g, Fat 14g", "storage": "Fridge 3–4 days; freezes well. Thin with stock to reheat.", "chefNotes": "Brown the meat first for deeper flavour.", "pairsWith": "Lemon wedges and bread.", "trivia": "Traditionally served during Ramadan to break the fast.", "howThisFeels": "Tomatoey, brothy and warming — the soup that opens the table at Ramadan.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-fricassee-tunisienne", "name": "Fricassée Tunisienne", "nameAlt": "Tuna Sandwich", "aliases": [], "course": "main", "type": ["main", "snack"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["street-food"], "ingredients": "1 baguette (80g) · 50g canned tuna · 1 boiled egg (sliced) · 30g fried potato cubes · 20g olives · harissa · 10ml olive oil · lemon", "method": "Fry the small rolls until crisp and golden, then split. Fill generously with the tuna, sliced boiled egg, fried potato cubes, olives and harissa, and drizzle with olive oil and a squeeze of lemon.", "cookTime": "20–25 min", "kcal": "~450–520 kcal", "nutrition": "Protein 22g, Carbs 48g, Fat 22g", "storage": "Best fresh.", "chefNotes": "Stuff generously and drizzle with harissa oil. A small bread roll works in place of the baguette.", "pairsWith": "Cold, as a picnic sandwich.", "trivia": "One of the most popular street foods in Tunis — a meal in a roll.", "howThisFeels": "A fried roll packed with tuna, egg and harissa — a whole meal you eat standing up.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-kabkabou", "name": "Kabkabou", "nameAlt": "Fish Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": [], "ingredients": "160g firm white fish (grouper/sea bass) · 80g tomatoes (blended) · 30g onion · 20g bell pepper · 10ml olive oil · 5g harissa · 3g garlic · 2g cumin · 30g preserved lemon · 100ml fish stock", "method": "Fry the onion and pepper in olive oil, add the garlic, harissa and cumin, then the blended tomato and stock. Add the preserved lemon and simmer 10 min. Slide in the fish and simmer gently 10–15 min until just cooked. Serve with couscous.", "cookTime": "35–45 min", "kcal": "~320–390 kcal", "nutrition": "Protein 32g, Fat 16g, Carbs 12g", "storage": "Fridge 2 days; reheat gently so the fish doesn't overcook.", "chefNotes": "Add the fish at the end to keep it tender.", "pairsWith": "Couscous.", "trivia": "A coastal specialty showcasing Tunisia's excellent seafood.", "howThisFeels": "White fish stewed with tomato, lemon and capers — the coast served in a shallow dish.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-ghraiba", "name": "Ghraiba", "nameAlt": "Shortbread Cookies", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": [], "ingredients": "50g semolina · 30g butter · 20g icing sugar · 5g orange blossom water · 10g almonds · pinch salt", "method": "Cream the butter (or ghee) with the icing sugar and orange blossom water, then work in the semolina and a pinch of salt to a soft dough; rest. Shape into balls or fingers, press an almond on top, and bake at 160°C 15–20 min until pale golden. Cool — they firm up as they cool.", "cookTime": "25–35 min", "kcal": "~260–310 kcal", "nutrition": "Carbs 35g, Fat 14g", "storage": "Airtight, up to 2 weeks.", "chefNotes": "Bake only until pale golden; don't over-colour. Ghee works in place of butter.", "pairsWith": "Mint tea.", "trivia": "Offered to guests; the melt-in-the-mouth texture is the signature.", "howThisFeels": "Melt-on-the-tongue shortbread — the crumbly cookie set out for every guest.", "servings": 1, "sharedWith": ""},
  {"id": "tunisia-bouza", "name": "Bouza", "nameAlt": "Millet Pudding Drink", "aliases": [], "course": "dessert", "type": ["dessert", "drink"], "diet": ["vegetarian"], "cuisine": "north-africa", "country": "Tunisia", "occasion": ["ramadan"], "ingredients": "40g millet flour · 200ml milk · 15g sugar · 5g orange blossom water · pinch cinnamon · crushed nuts (topping)", "method": "Whisk the millet flour into the milk with the sugar and cook over low heat, stirring, until thick and creamy (10–15 min). Stir in the orange blossom water and cinnamon. Chill, then serve cold topped with crushed nuts.", "cookTime": "20–30 min + chilling", "kcal": "~180–230 kcal", "nutrition": "Carbs 32g, Protein 8g, Fat 6g", "storage": "Fridge 3 days.", "chefNotes": "Cook until thick and creamy; serve well chilled.", "pairsWith": "After spicy meals.", "trivia": "A refreshing summer drink-dessert, popular during Ramadan.", "howThisFeels": "Cool millet cream scented with orange blossom — a summer's-end spoonful, half drink, half dessert.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-sadza", "name": "Sadza", "nameAlt": "Maize Meal Porridge", "aliases": [], "course": "side", "type": ["main", "side"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["everyday"], "ingredients": "100g maize meal (mealie meal) · 400ml water · Pinch of salt (2g)", "method": "Bring 300ml water + salt to boil. Mix 30g maize meal with 100ml cold water into paste. Stir into boiling water. Gradually add remaining maize meal, stirring vigorously with a wooden spoon until thick and pulls away from pot (10-15 min total). Cook on low 5-10 min more.", "cookTime": "20–30 min", "kcal": "~350–400 kcal (mostly carbs)", "nutrition": "Carbs 70-80g, Protein 8-10g, Fat 2g, Fiber 4-6g. Rich in fortified vitamins if using commercial mealie meal.", "storage": "Best fresh. Refrigerate up to 2 days. Reheat with a splash of water or fry into sadza bhora (balls). Plan for 10-20% extra for big events.", "chefNotes": "Stir constantly to avoid lumps. Use fine white maize meal for traditional texture.", "pairsWith": "Any stew, greens (muriwo), or meat. Goes with everything.", "trivia": "Introduced widely during colonial times but now a symbol of Zimbabwean identity. Traditionally eaten by hand, rolled into balls to scoop relish. Women often prepare it daily.", "howThisFeels": "Plain, warm and shaped by hand — the maize at the centre of every Zimbabwean meal.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-muriwo-unedovi", "name": "Muriwo Unedovi", "nameAlt": "Greens in Peanut Butter", "aliases": [], "course": "side", "type": ["side"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["everyday"], "ingredients": "200g kale (chopped) · 20g peanut butter (natural) · 50g onion (chopped) · 50g tomato (chopped) · 5g garlic (minced) · 10ml oil · 100ml water · Salt, pepper, chili to taste", "method": "Sauté onion/garlic/tomato in oil. Add greens and water; cook until wilted. Stir in peanut butter; simmer 5-10 min until creamy.", "cookTime": "20–25 min", "kcal": "~180–220 kcal", "nutrition": "Protein 8-10g, Fat 12g (from PB), Carbs 15g, high in Vitamins A/K/C, iron, fiber.", "storage": "Fridge 3-4 days. Freezes well. Reheat gently; add water if thick. Good cold in wraps.", "chefNotes": "Use pumpkin leaves (muboora) seasonally for authenticity. Don't overcook greens. Collard greens (covo) or spinach work in place of kale.", "pairsWith": "Sadza + meat stew.", "trivia": "Everyday family dish highlighting Zimbabwe’s love for peanut butter (introduced via Portuguese influence centuries ago). Traditionally prepared by women.", "howThisFeels": "Greens turned silky with peanut butter — the everyday side Zimbabwe can't do without.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-huku-ne-dovi", "name": "Huku ne Dovi", "nameAlt": "Chicken in Peanut Stew", "aliases": ["Dovi"], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["celebration"], "ingredients": "150g chicken pieces (bone-in for flavor) · 30g peanut butter · 50g onion · 50g tomato · 50g mixed veg (carrots, greens, okra optional) · 5g garlic · 10ml oil · 150ml water · Spices: curry powder, salt, chili", "method": "Brown chicken. Sauté aromatics, add chicken + liquid; simmer 30-40 min. Stir in peanut butter last 10 min.", "cookTime": "45–60 min", "kcal": "~350–450 kcal", "nutrition": "Protein 25-30g, Fat 20g, Carbs 15g.", "storage": "Fridge 3-4 days; freeze 2-3 months. Excellent next day as flavors meld. Reheat slowly.", "chefNotes": "Adjust thickness with liquid. Use natural peanut butter.", "pairsWith": "Sadza or rice; fresh salad.", "trivia": "Peanut stews reflect historical trade influences. Comfort food for celebrations and family gatherings.", "howThisFeels": "Chicken in a rich peanut gravy — the comfort stew kept for the people you love.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-nyama-with-greens", "name": "Nyama with Greens", "nameAlt": "Beef Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["celebration", "everyday"], "ingredients": "150g beef (brisket or stewing) · 50g onion · 50g tomato · 100g kale · 5g garlic · 10ml oil · 150ml water · Spices (curry, salt, pepper)", "method": "Brown beef, sauté veggies, simmer 1-1.5 hours until tender. Add greens last 15 min.", "cookTime": "1.5–2 hours", "kcal": "~300–400 kcal", "nutrition": "Protein 25g, Fat 15-20g, Carbs 10g, iron-rich.", "storage": "Similar to Dovi – improves with time.", "chefNotes": "Slow cook for tenderness. Covo or other greens work in place of kale.", "pairsWith": "Sadza, sadza ne maguru (tripe) variation popular.", "trivia": "Highfields/Hifiridzi variation originated in Harare suburb – everyday celebratory food.", "howThisFeels": "Slow beef and tender greens — a Highfields plate that turns any day into an occasion.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-mopane-worms-relish", "name": "Mopane Worms Relish", "nameAlt": "Madora", "aliases": [], "course": "side", "type": ["side", "main"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "40-50g dried mopane worms (rehydrated) · 50g tomato · 50g onion · 5g garlic · 10ml oil · spices, salt", "method": "Soak worms, boil, then fry/simmer with tomato-onion gravy.", "cookTime": "30–45 min (after soaking)", "kcal": "~150–200 kcal (high protein)", "nutrition": "Protein 20-30g+, iron, calcium.", "storage": "Dried worms last months; cooked 3-4 days fridge.", "chefNotes": "Thoroughly clean. Crunchy when roasted.", "pairsWith": "Sadza.", "trivia": "Harvested from mopane trees seasonally; highly nutritious \"bush food\" delicacy providing protein in rural areas.", "howThisFeels": "Earthy, chewy and proudly traditional — bush protein gathered from the mopane trees.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-nhopi", "name": "Nhopi", "nameAlt": "Pumpkin & Peanut Mash", "aliases": [], "course": "dessert", "type": ["dessert", "side"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "200g pumpkin (cooked/mashed) · 20g peanut butter · 10g sugar (optional) · Pinch salt · 100ml water", "method": "Boil or steam the pumpkin until very soft, then mash smooth. Stir in the peanut butter with a little water or milk over low heat until creamy and well combined. Sweeten with a touch of sugar or honey if you like, add a pinch of salt, and simmer about 5 min until thick. Serve warm.", "cookTime": "20–30 min", "kcal": "~200 kcal. Nutritious and creamy", "nutrition": "", "storage": "", "chefNotes": "Honey instead of sugar works; a splash of milk in place of water makes it creamier.", "pairsWith": "As side or sweet end to meal.", "trivia": "Traditional comforting porridge using local pumpkin.", "howThisFeels": "Pumpkin mashed soft with peanut butter — a warm, sweet porridge that tastes like childhood.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-chikenduza", "name": "Chikenduza", "nameAlt": "Sweet Steamed Bread", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["celebration"], "ingredients": "25g flour · 5g butter · 12g sugar · pinch yeast · 10ml milk · vanilla · pink glacé icing", "method": "Make a soft yeast dough with the flour, butter, sugar, milk and vanilla; knead and prove until doubled. Shape into small buns, prove again, then bake at 180°C 15–20 min until golden. Cool and top with a bright pink glacé icing.", "cookTime": "20 min bake after proofing", "kcal": "~150–200 kcal", "nutrition": "", "storage": "Airtight 2-3 days.", "chefNotes": "", "pairsWith": "", "trivia": "Festive sweet yeast cakes with bright pink glaze – fun treat for kids and celebrations.", "howThisFeels": "Soft yeast cakes under bright pink icing — the festive treat that makes children's eyes light up.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-muboora", "name": "Muboora", "nameAlt": "Pumpkin Leaves", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "200g fresh pumpkin leaves (chopped) · 20g peanut butter (optional for unedovi style) · 50g tomato (chopped) · 50g onion (chopped) · 5g garlic · 10ml oil · 2g baking soda (for tenderness) · 100ml water · Salt to taste", "method": "Strip and chop the young pumpkin leaves, adding a little baking soda to the cooking water to keep them tender and green. Fry the onion, garlic and tomato in oil, then add the leaves with a splash of water and simmer until tender. Stir in the peanut butter for the dovi style and season with salt.", "cookTime": "20–25 min", "kcal": "~120–180 kcal (higher with PB)", "nutrition": "Protein 6-8g, Fat 8-12g, Carbs 12g, high in Vitamins A, C, iron, fiber.", "storage": "Fridge 3 days. Freezes well. Reheat with splash of water; good mixed into sadza.", "chefNotes": "Remove tough stems. Add PB for creamier version.", "pairsWith": "Sadza, grilled meat.", "trivia": "Seasonal favorite using leaves from pumpkin plants – nothing wasted in traditional Zimbabwean cooking. Often prepared by women in rural households.", "howThisFeels": "Tender pumpkin leaves cooked simple — proof that in a Zimbabwean garden, nothing goes to waste.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-sadza-ne-maguru", "name": "Sadza ne Maguru", "nameAlt": "Tripe", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["celebration"], "ingredients": "150g cleaned beef tripe (maguru) · 50g onion · 50g tomato · 5g garlic · 10ml oil · 150ml stock · Spices (curry powder 2g, salt, chili)", "method": "Clean and boil the tripe until very tender (1½–2 hrs, or pressure-cook). Fry the onion, garlic and tomato in oil with the curry powder and chilli, then add the cooked tripe and a little stock and simmer 15–20 min until rich. Season and serve with sadza.", "cookTime": "2–2.5 hours (tripe needs long cooking)", "kcal": "~280–350 kcal", "nutrition": "Protein 25g, Fat 12g, Carbs 10g, collagen-rich.", "storage": "Fridge 3-4 days. Flavors improve; reheat slowly.", "chefNotes": "Clean thoroughly; pressure cooker speeds it up.", "pairsWith": "Plain sadza.", "trivia": "Beloved \"soul food\" dish, popular in townships like Highfields. Offal celebrates resourcefulness.", "howThisFeels": "Tripe slow-cooked to tenderness — township soul food that celebrates making more from less.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-matemba", "name": "Matemba", "nameAlt": "Kapenta", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["pescatarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "40g dried kapenta (matemba), soaked · 50g tomato · 50g onion · 5g garlic · 10ml oil · 100ml water · Chili, salt", "method": "Soak the dried kapenta briefly and drain. Fry the onion, garlic and tomato in oil until soft, add the fish and a little water, and simmer 10–15 min until the sauce thickens and clings. Season with chilli and salt; serve with sadza.", "cookTime": "25–35 min", "kcal": "~160–200 kcal", "nutrition": "Protein 20g+, calcium (bones), omega-3.", "storage": "Dried long-term; cooked 3 days fridge.", "chefNotes": "Fry briefly first for crunch.", "pairsWith": "Sadza and greens.", "trivia": "Affordable protein from Lake Kariba; tiny fish eaten whole.", "howThisFeels": "Tiny lake fish fried whole and crisp — affordable, salty, eaten down to the very last one.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-derere", "name": "Derere", "nameAlt": "Okra Stew/Relish", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "150g fresh or frozen okra (sliced) · 50g tomato · 50g onion · 5g garlic · 10ml oil · 80ml water · Salt, chili", "method": "Fry the onion, garlic and tomato in oil until soft. Add the sliced okra and a little water and simmer 10–15 min, stirring, until tender and naturally thickened — the prized slippery texture. Season with salt and chilli.", "cookTime": "20–30 min", "kcal": "~100–140 kcal", "nutrition": "High fiber, vitamins, mucilaginous texture.", "storage": "Fridge 3 days.", "chefNotes": "Don't overcook or it gets too slimy for some.", "pairsWith": "Sadza with meat.", "trivia": "Classic relish showcasing okra's natural thickening.", "howThisFeels": "Glossy okra relish that draws into threads — the slippery side Zimbabwe loves on its sadza.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-gango", "name": "Gango", "nameAlt": "Mixed Meat Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["celebration"], "ingredients": "80g beef · 60g chicken · 40g sausage · 60g onion · 60g tomato · 100g greens · 10ml oil · 150ml stock · Spices", "method": "Brown the mixed meats in oil in a heavy pot. Add the onion and tomato and cook down, then pour in the stock with the spices and simmer until the meats are tender. Stir in the greens for the last few minutes. Often finished braai-style over the coals.", "cookTime": "1–1.5 hours", "kcal": "~400–500 kcal", "nutrition": "High protein ~35g.", "storage": "Excellent reheated.", "chefNotes": "Celebration dish – mix cheaper cuts.", "pairsWith": "Sadza.", "trivia": "Festive \"meat medley\" for gatherings and special occasions.", "howThisFeels": "A medley of beef, chicken and sausage — the meat feast that means people are gathering.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-mupotohayi", "name": "Mupotohayi", "nameAlt": "Cornmeal Bread", "aliases": ["Chimodho"], "course": "side", "type": ["side", "breakfast"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": ["breakfast"], "ingredients": "60g maize meal · 30g wheat flour · 10g sugar · 5g baking powder · 80ml milk · Pinch salt", "method": "Mix the maize meal, wheat flour, sugar, baking powder and salt, then stir in the milk or water to a thick batter. Pour into a greased tin and bake at 180°C 30–40 min (or steam) until firm and golden. Cool, slice and serve with tea.", "cookTime": "30–40 min (steamed/baked)", "kcal": "~180–220 kcal", "nutrition": "Carbs focused.", "storage": "2-3 days airtight.", "chefNotes": "Water works in place of milk.", "pairsWith": "", "trivia": "Traditional steamed bread, often made for breakfast or tea.", "howThisFeels": "Lightly sweet steamed cornbread — the breakfast loaf that pairs with morning tea.", "servings": 1, "sharedWith": ""},
  {"id": "zimbabwe-mapopo-candy", "name": "Mapopo Candy", "nameAlt": "Papaya Candy", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Zimbabwe", "occasion": [], "ingredients": "100g green papaya (cubed) · 50g sugar · 50ml water · Lemon juice (5ml) · Vanilla optional", "method": "Simmer the cubed green papaya with the sugar, water and lemon juice over low heat, stirring, until the syrup thickens and coats the fruit. Stir in a little vanilla and keep cooking until sticky and glossy. Cool on a tray until set and chewy.", "cookTime": "45–60 min (simmer to candy)", "kcal": "~150–200 kcal", "nutrition": "", "storage": "Airtight weeks.", "chefNotes": "Cook until chewy.", "pairsWith": "After heavy sadza meals.", "trivia": "Homemade sweet using local papaya – popular affordable treat.", "howThisFeels": "Sugared green papaya, chewy and bright — the homemade sweet sold for a few coins.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-xima", "name": "Xima", "nameAlt": "Maize Meal Porridge", "aliases": [], "course": "side", "type": ["main", "side"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["everyday"], "ingredients": "100g maize meal (cornmeal) · 400ml water · 2g salt", "method": "Bring the salted water to the boil. Gradually stir in the maize meal, beating hard with a wooden spoon, and cook over low heat 15–20 min until thick, smooth and pulling from the pot. Shape and turn out; serve with stew or relish.", "cookTime": "20–25 min", "kcal": "~350–380 kcal", "nutrition": "Carbs 75g, Protein 8g, Fat 2g, Fiber 4g.", "storage": "Best fresh. Fridge up to 2 days. Reheat with water or fry leftover balls.", "chefNotes": "Stir vigorously to avoid lumps; use fine white cornmeal.", "pairsWith": "Matapa, piri-piri chicken, or any stew.", "trivia": "The cornerstone of Mozambican meals. Traditionally eaten by hand to scoop up sauces.", "howThisFeels": "Plain cornmeal scooped by hand — the quiet base every Mozambican sauce leans on.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-matapa", "name": "Matapa", "nameAlt": "Cassava Leaves, Peanut & Coconut", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "200g cassava leaves (finely chopped) · 30g ground peanuts · 100ml coconut milk · 50g onion (chopped) · 5g garlic (minced) · 100g shrimp (optional, peeled) · 10ml oil · 100ml water · Salt, chili to taste", "method": "Finely chop or pound the cassava leaves and simmer in water until tender. Add the onion, garlic, ground peanuts and coconut milk and cook gently until thick and creamy. Stir in the shrimp (if using) for the last few minutes. Season with salt and chilli; serve with rice or xima.", "cookTime": "30–45 min", "kcal": "~280–380 kcal (with shrimp)", "nutrition": "Protein 12-20g, Fat 18g, Carbs 15g, high in Vitamins A & iron.", "storage": "Fridge 3 days; freezes well. Flavors deepen — reheat gently with splash of coconut milk.", "chefNotes": "Pound or finely chop leaves traditionally. Adjust thickness with coconut milk. Spinach or kale work in place of cassava leaves; 25g peanut butter instead of ground peanuts.", "pairsWith": "Xima or rice.", "trivia": "Ancient dish with minimal Portuguese influence. Symbol of local resourcefulness using cassava plant leaves.", "howThisFeels": "Cassava leaves and coconut pounded to a deep green stew — pure pre-colonial comfort.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-frango-piri-piri", "name": "Frango Piri-Piri", "nameAlt": "Peri-Peri Chicken", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "200g chicken pieces (thighs/drumsticks) · 15ml piri-piri sauce (or homemade with bird's eye chilies) · 10ml lemon juice · 5g garlic (minced) · 5ml oil · 2g paprika · Salt to taste", "method": "Marinate the chicken in the piri-piri, garlic, lemon, paprika and salt at least 30 min. Grill over charcoal (or roast), basting with the marinade, until charred and cooked through. Serve with extra piri-piri.", "cookTime": "40–60 min (grill or oven)", "kcal": "~350–420 kcal", "nutrition": "Protein 30g, Fat 20g, Carbs 4g.", "storage": "Fridge 3-4 days. Great cold in sandwiches or reheated.", "chefNotes": "Use bone-in for juiciness. Grill over open flame traditionally.", "pairsWith": "Xima, coconut rice, or chips.", "trivia": "Originated from Portuguese-African fusion in Mozambique. The famous Nando’s chain is inspired by this dish.", "howThisFeels": "Chicken charred and slicked with fiery piri-piri — the flame that inspired a whole chain.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-caril-de-camarao", "name": "Caril de Camarão", "nameAlt": "Shrimp Curry", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "150g shrimp (peeled) · 100ml coconut milk · 50g tomato (chopped) · 50g onion (chopped) · 5g garlic · 5g fresh ginger · 5g curry powder · 10ml oil · Chili, salt, lemon", "method": "Fry the onion, garlic and ginger in oil, add the curry powder and tomato and cook down. Pour in the coconut milk and simmer a few minutes, then add the shrimp and cook 3–5 min until just pink. Finish with chilli, salt and lemon.", "cookTime": "25–35 min", "kcal": "~320–380 kcal", "nutrition": "Protein 25g, Fat 18g, Carbs 10g.", "storage": "Fridge 2-3 days. Excellent next day.", "chefNotes": "Don't overcook shrimp.", "pairsWith": "Coconut rice or Xima.", "trivia": "Reflects strong Indian and Portuguese influences along the coast.", "howThisFeels": "Coastal shrimp in spiced coconut — India and Portugal meeting on the Indian Ocean shore.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-frango-a-zambeziana", "name": "Frango à Zambeziana", "nameAlt": "Zambezia Chicken", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration"], "ingredients": "200g chicken pieces · 120ml coconut milk · 50g onion · 5g garlic · 10ml oil · Piri-piri or chili to taste · Salt, lemon", "method": "Marinate the chicken with the garlic, chilli, lemon and salt. Grill or pan-sear, then simmer in the coconut milk with the onion until tender and the sauce is rich. Baste with piri-piri; serve with rice.", "cookTime": "45–60 min", "kcal": "~380–450 kcal", "nutrition": "Protein 32g, Fat 25g.", "storage": "Improves overnight.", "chefNotes": "Slow simmer for tenderness.", "pairsWith": "Rice or Xima.", "trivia": "Celebrated regional specialty showcasing Mozambique’s abundant coconuts.", "howThisFeels": "Chicken simmered in Zambezia coconut — a regional pride you can smell from the gate.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-chamussas", "name": "Chamussas", "nameAlt": "Spiced Samosas", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration", "street-food"], "ingredients": "60g minced beef · 50g onion · 5g garlic · 5g curry spices · 15g pastry wrappers · Oil for frying (20ml absorbed)", "method": "Fry the onion, garlic and curry spices in a little oil, add the mince and cook until dry; cool. Fill the pastry wrappers, fold into triangles and seal the edges well. Deep-fry until golden and crisp; drain.", "cookTime": "30–40 min (including frying)", "kcal": "~250–320 kcal", "nutrition": "Protein 15g, Fat 15g, Carbs 20g.", "storage": "Best fresh. Fridge 2 days.", "chefNotes": "Seal well to prevent bursting. Chicken works in place of beef.", "pairsWith": "As starter with meals or snacks.", "trivia": "Popular street food and party item, showing Indian influence.", "howThisFeels": "Crisp, spiced little triangles — the street snack that says someone's celebrating.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-bolo-polana", "name": "Bolo Polana", "nameAlt": "Cashew & Potato Cake", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration"], "ingredients": "50g mashed potato · 40g ground cashews · 30g sugar · 20g butter · 1/4 egg (scale accordingly) · Zest of 1/4 orange, lemon · Vanilla", "method": "Cream the butter and sugar, then beat in the egg, orange and lemon zest and vanilla. Fold in the mashed potato and ground cashews to a soft batter. Spread in a tin and bake at 180°C 35–45 min until golden and set.", "cookTime": "50–60 min baking", "kcal": "~280–320 kcal", "nutrition": "Carbs 30g, Fat 18g, Protein 6g.", "storage": "Airtight 3-4 days.", "chefNotes": "Use smooth mashed potatoes.", "pairsWith": "Tea or coffee after meals.", "trivia": "Named after a famous upscale neighborhood in Maputo. Festive cake loved for its unique potato-cashew combination.", "howThisFeels": "Cashew-and-potato cake, dense and golden — Maputo elegance named for its smartest street.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-matata", "name": "Matata", "nameAlt": "Clam & Peanut Greens Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "60g clams · 50g prawns · 40g fish · 150g cassava leaves (chopped finely) · 30g ground peanuts · 80ml coconut milk · 50g onion (chopped) · 5g garlic (minced) · 10ml oil · 100ml water · Salt, chili to taste", "method": "Simmer the cassava leaves (or spinach) in water until tender. Add the onion, garlic, ground peanuts and coconut milk and cook to a thick sauce. Stir in the mixed seafood and simmer 5–8 min until just cooked. Season with salt and chilli; serve with rice.", "cookTime": "35–45 min", "kcal": "~320–400 kcal", "nutrition": "Protein 25g, Fat 18g, Carbs 15g, high in iron and vitamins.", "storage": "Fridge 2-3 days. Reheat gently; flavors improve.", "chefNotes": "Finely chop or pound leaves for smooth texture. Spinach works in place of cassava leaves; peanut butter instead of ground peanuts.", "pairsWith": "Xima or rice.", "trivia": "A pre-colonial Bantu dish highlighting Mozambique’s abundant seafood and local greens.", "howThisFeels": "Clams and greens stewed together — an ancient Bantu taste of the shoreline.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-camarao-mozambique", "name": "Camarão Mozambique", "nameAlt": "Shrimp Mozambique", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "180g shrimp (peeled and deveined) · 20g butter · 10ml oil · 8g garlic (minced) · 5ml lemon juice · 50ml beer · 5g paprika · Piri-piri or chili to taste · Salt", "method": "Melt the butter with the oil and fry the garlic until fragrant. Add the shrimp, paprika and piri-piri and sauté 2–3 min, then deglaze with the beer or wine and lemon. Simmer briefly until the shrimp are pink and the sauce glossy; season.", "cookTime": "20–25 min", "kcal": "~280–350 kcal", "nutrition": "Protein 28g, Fat 18g, Carbs 5g.", "storage": "Fridge 2 days. Excellent in sandwiches or pasta.", "chefNotes": "Cook shrimp quickly to avoid toughness. White wine works in place of beer.", "pairsWith": "Rice or crusty bread to soak up sauce.", "trivia": "A Portuguese-African fusion dish famous for its bold garlic and piri-piri kick.", "howThisFeels": "Shrimp swimming in garlic-butter and piri-piri — bold, messy and worth the napkins.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-rissois-de-camarao", "name": "Rissóis de Camarão", "nameAlt": "Shrimp Rissoles", "aliases": [], "course": "starter", "type": ["starter"], "diet": ["pescatarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration", "street-food"], "ingredients": "100g shrimp (chopped) · 50g onion · 5g garlic · 10g flour (for sauce) · 80ml milk · 60g pastry dough · Oil for frying (20ml absorbed) · Salt, pepper, chili", "method": "Make a thick white sauce with the flour, milk and seasonings, then stir in the chopped shrimp, onion and garlic; cool until firm. Spoon onto pastry rounds, fold into half-moons and seal, then crumb and deep-fry until golden.", "cookTime": "40–50 min (including frying)", "kcal": "~300–380 kcal", "nutrition": "Protein 18g, Fat 18g, Carbs 25g.", "storage": "Best fresh; fridge 1-2 days.", "chefNotes": "Make thick béchamel for filling.", "pairsWith": "As starter before main seafood dishes.", "trivia": "Popular party and street food, showing Portuguese influence on snacks.", "howThisFeels": "Creamy shrimp tucked in fried pastry crescents — the party bite that never lasts.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-badjia", "name": "Badjia", "nameAlt": "Black-Eyed Bean Fritters", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["breakfast", "street-food"], "ingredients": "60g black-eyed pea flour (or soaked & blended peas) · 30g onion (finely chopped) · 5g garlic · 2g turmeric · Chili, salt · Water to form batter · Oil for frying", "method": "Blend the soaked peas (or pea flour) with the onion, garlic, turmeric and chilli into a thick batter, whisking well for fluffiness. Season, then drop spoonfuls into hot oil and fry until golden and crisp; drain.", "cookTime": "25–35 min", "kcal": "~220–280 kcal", "nutrition": "Protein 12g, Carbs 25g.", "storage": "Best hot; fridge 2 days.", "chefNotes": "Ferment batter slightly for authentic taste. A pinch of saffron in place of turmeric for colour.", "pairsWith": "Bread or as side.", "trivia": "Indian-influenced street snack sold everywhere, especially for quick breakfast (\"matabicho\").", "howThisFeels": "Spiced bean fritters off a morning cart — the breakfast that wakes Maputo up.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-fofos-de-arroz", "name": "Fofos de Arroz", "nameAlt": "Sweet Rice Fritters", "aliases": [], "course": "starter", "type": ["starter", "side"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration"], "ingredients": "80g cooked rice · 50g shrimp (optional) · 30g onion · 5g garlic · 1/4 egg (beaten) · Breadcrumbs for coating · Oil for frying", "method": "Mix the cooked rice with the chopped shrimp or meat, onion, garlic and beaten egg, and season. Shape into balls, coat in breadcrumbs, and deep-fry until golden and crisp; drain. Serve with a dipping sauce.", "cookTime": "30–40 min", "kcal": "~250–320 kcal", "nutrition": "", "storage": "Best fresh.", "chefNotes": "Chill mixture before forming balls. Minced meat works in place of shrimp.", "pairsWith": "Dipping sauces.", "trivia": "Crunchy, addictive party food loved across the country.", "howThisFeels": "Crunchy little rice puffs — the addictive nibble that empties the plate.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-etoritory", "name": "Doce de Amendoim", "nameAlt": "Peanut & Coconut Sweet", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["street-food"], "ingredients": "50g peanuts (ground) · 40g sugar · 30ml coconut milk · Pinch salt · Cinnamon optional", "method": "Toast and grind the peanuts. Cook the sugar with a little coconut milk to a syrup, stir in the ground peanuts, salt and cinnamon, and cook until thick. Press into a tray, cool, and cut into pieces.", "cookTime": "20–30 min + setting", "kcal": "~180–220 kcal", "nutrition": "Fat 12g, Carbs 18g, Protein 6g.", "storage": "Airtight 1 week.", "chefNotes": "Cook to soft-ball stage.", "pairsWith": "After spicy meals.", "trivia": "Affordable homemade treat made by women and children on streets – melts in your mouth.", "howThisFeels": "Ground peanut and coconut melting sweet — the street treat made by women and children.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-pudim", "name": "Pudim", "nameAlt": "Baked Caramel Custard", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration"], "ingredients": "80ml milk · 1/4 egg · 20g sugar (for caramel + custard) · Vanilla essence · Lemon zest", "method": "Melt sugar to an amber caramel and pour into the moulds. Whisk the milk, eggs, remaining sugar, vanilla and lemon zest, strain over the caramel, and bake in a water bath at 160°C until just set. Chill, then turn out.", "cookTime": "50–70 min (bain-marie)", "kcal": "~160–200 kcal", "nutrition": "", "storage": "Fridge 3-4 days.", "chefNotes": "Caramelize sugar carefully for topping.", "pairsWith": "Coffee or tea.", "trivia": "Common at celebrations and festivities, a beloved Portuguese legacy.", "howThisFeels": "Silky caramel custard — the Portuguese legacy that closes every celebration.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-arroz-de-coco", "name": "Arroz de Coco", "nameAlt": "Coconut Rice", "aliases": [], "course": "side", "type": ["side"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["everyday"], "ingredients": "80g long-grain rice (uncooked) · 150ml coconut milk · 100ml water · 5g onion (finely chopped) · 5ml oil · 2g salt", "method": "Soften the onion in the oil. Add the rice, coconut milk, water and salt, bring to a boil, then cover and cook on low 18–20 min until absorbed and tender. Rest and fluff.", "cookTime": "25–30 min", "kcal": "~280–320 kcal", "nutrition": "Carbs 45g, Fat 12g, Protein 5g.", "storage": "Fridge 3 days. Reheat with splash of water; fry into rice cakes.", "chefNotes": "Rinse rice well; don't stir too much while cooking.", "pairsWith": "Curries, grilled chicken or shrimp.", "trivia": "Highlights Mozambique’s abundant coconuts; everyday staple in coastal regions replacing plain rice.", "howThisFeels": "Rice cooked in coconut milk — the fragrant everyday staple of the coast.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-caranguejo-com-coco", "name": "Caranguejo com Coco", "nameAlt": "Coconut Crab Curry", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "200g fresh crab pieces (cleaned) · 120ml coconut milk · 50g onion (chopped) · 5g garlic (minced) · 5g ginger (grated) · 50g tomato (chopped) · 10ml oil · 5g curry powder · chili, piri-piri, salt to taste", "method": "Fry the onion, garlic and ginger in oil, add the tomato, curry powder and chilli and cook down. Pour in the coconut milk and simmer, then add the crab pieces and cook 10–15 min until done and the sauce is rich. Season.", "cookTime": "35–45 min", "kcal": "~320–390 kcal", "nutrition": "Protein 28g, Fat 20g, Carbs 10g, high in minerals.", "storage": "Fridge 2 days. Reheat gently; excellent next day.", "chefNotes": "Cook crab just until done to keep it tender. Paprika works in place of curry powder.", "pairsWith": "Xima or coconut rice.", "trivia": "Traditional in fishing communities; showcases the fusion of local seafood with coconut and spices.", "howThisFeels": "Crab simmered in coconut curry — a fishing-village feast for cracked-shell fingers.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-galinha-a-africana", "name": "Galinha à Africana", "nameAlt": "African Chicken", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["celebration"], "ingredients": "200g chicken pieces · 100ml coconut milk · 50g onion · 5g garlic · 10ml oil · 5g curry spices · piri-piri · 50g tomato · Salt, lemon juice", "method": "Marinate the chicken in garlic, piri-piri, lemon and salt. Brown in oil, add the onion and tomato, then the coconut milk or stock, and simmer until tender and the sauce thickens. Serve with rice.", "cookTime": "45–60 min", "kcal": "~360–430 kcal", "nutrition": "Protein 32g, Fat 22g, Carbs 8g.", "storage": "Fridge 3-4 days. Flavors improve overnight.", "chefNotes": "Balance heat with coconut creaminess. Stock works in place of coconut milk for a lighter sauce.", "pairsWith": "Rice or Xima.", "trivia": "A hearty \"African-style\" chicken dish popular for family gatherings.", "howThisFeels": "Hearty African-style chicken — the big-pot dish that gathers the family.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-salada-de-polvo", "name": "Salada de Polvo", "nameAlt": "Octopus Salad", "aliases": [], "course": "starter", "type": ["starter"], "diet": ["pescatarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "150g cooked octopus (sliced) · 50g tomato (diced) · 50g onion (sliced) · 5ml olive oil · 5ml lemon juice · Fresh coriander (5g) · Salt, chili flakes", "method": "Slice the cooked octopus and toss with the diced tomato and onion. Dress with olive oil, lemon, coriander, salt and chilli flakes, and chill before serving.", "cookTime": "15–20 min (after octopus prep)", "kcal": "~180–220 kcal", "nutrition": "Protein 25g, Fat 8g, low carb.", "storage": "Fridge 2 days.", "chefNotes": "Tenderize octopus by boiling first.", "pairsWith": "As starter with bread or before seafood mains.", "trivia": "Fresh seafood salads reflect Mozambique’s long coastline and Portuguese influence on cold dishes.", "howThisFeels": "Cool octopus tossed with tomato and onion — the long coastline served chilled.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-prego", "name": "Prego", "nameAlt": "Steak Sandwich", "aliases": [], "course": "main", "type": ["main", "snack"], "diet": [], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["street-food", "everyday"], "ingredients": "150g thin beef steak · 1 bread roll (80g) · 5g garlic (minced) · 10ml oil · Piri-piri sauce (5ml) · Salt, lemon", "method": "Rub the thin steak with garlic and salt. Sear quickly in hot oil, 1–2 min a side, splash with piri-piri and lemon, and pile into a crusty roll with the pan juices.", "cookTime": "15–20 min", "kcal": "~450–520 kcal", "nutrition": "Protein 30g, Carbs 35g, Fat 20g.", "storage": "Best fresh.", "chefNotes": "Quick sear for juicy steak.", "pairsWith": "Fries or salad.", "trivia": "Everyday lunch favorite in Maputo, showing Portuguese \"prego\" steak influence.", "howThisFeels": "Garlicky steak crammed into a roll — Maputo's no-nonsense lunch.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-mandioca-frita", "name": "Mandioca Frita", "nameAlt": "Fried Cassava", "aliases": [], "course": "side", "type": ["side", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": ["everyday"], "ingredients": "200g cassava root (peeled & boiled) · 10ml oil (for frying) · Salt to taste · Optional chili seasoning", "method": "Peel and boil the cassava until just tender, then cut into chips and pat dry. Deep- or shallow-fry in hot oil until golden and crisp. Drain, salt, and dust with chilli if you like.", "cookTime": "25–30 min (including boiling)", "kcal": "~220–280 kcal", "nutrition": "Carbs 40g, Fiber high.", "storage": "Best fresh; fridge 2 days.", "chefNotes": "Boil until soft before frying for crisp exterior.", "pairsWith": "With grilled meats or as snack.", "trivia": "Cassava is a key staple; frying it makes a beloved crunchy treat.", "howThisFeels": "Cassava fried to a golden crunch — the humble staple turned into a treat.", "servings": 1, "sharedWith": ""},
  {"id": "mozambique-ananas-com-vinho-do-porto", "name": "Ananás com Vinho do Porto", "nameAlt": "Pineapple in Port Wine", "aliases": [], "course": "dessert", "type": ["dessert"], "diet": ["vegan", "vegetarian"], "cuisine": "southern-africa", "country": "Mozambique", "occasion": [], "ingredients": "150g fresh pineapple (cubed) · 30ml port wine · 10g sugar (optional) · Mint leaves for garnish", "method": "Cube the fresh pineapple and toss with the port (and a little sugar if needed). Chill at least 30 min to macerate, then serve garnished with mint.", "cookTime": "5–10 min (no-cook or light simmer)", "kcal": "~120–160 kcal", "nutrition": "Carbs 20g, low fat.", "storage": "Fridge 2-3 days.", "chefNotes": "Marinate 30+ minutes for best flavor. Sweet red wine works in place of port.", "pairsWith": "After rich curries.", "trivia": "Light, refreshing end to meals – a Portuguese-inspired treat using local tropical fruit.", "howThisFeels": "Sweet pineapple steeped in port — a light, tropical flourish to end on.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-jollof-rice", "name": "Jollof Rice", "nameAlt": "Spiced Tomato Rice", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration"], "ingredients": "80g long-grain parboiled rice · 100g tomatoes (blended) · 50g red bell pepper (blended) · 30g onion (sliced + blended) · 10g tomato paste · 15ml vegetable oil · 5g Scotch bonnet pepper (adjust for heat) · 2g thyme · 2g curry powder · 1g bay leaf · 150ml stock (chicken/beef/veg) · Salt to taste", "method": "Blend the tomatoes, red pepper, onion and Scotch bonnet. Fry the tomato paste in oil, add the blended mix and cook down to a deep red base with the thyme, curry and bay. Stir in the rice and stock, cover, and cook on low until absorbed and tender — let the base catch slightly for the smoky party-jollof flavour. Season.", "cookTime": "45–60 min", "kcal": "~380–450 kcal", "nutrition": "Carbs 65g, Protein 8-10g, Fat 12g, Vitamin C rich.", "storage": "Fridge 3-4 days. Reheat with splash of stock; fry leftovers for \"jollof spaghetti\" twist.", "chefNotes": "Blend peppers/tomatoes smoothly; achieve \"smoky\" flavor by slight burning at the base. Palm oil instead of vegetable oil is more traditional.", "pairsWith": "Fried plantains (dodo), coleslaw, grilled chicken or moi moi.", "trivia": "Sparks \"Jollof wars\" across West Africa; a must-have at Nigerian weddings and celebrations.", "howThisFeels": "Smoky, tomato-red and fiercely defended — the rice that starts friendly wars across West Africa.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-egusi-soup", "name": "Egusi Soup", "nameAlt": "Melon Seed Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": [], "ingredients": "30g ground egusi seeds · 150g stewing beef (or beef + tripe/shaki) · 100g spinach (chopped) · 15ml palm oil · 30g tomatoes · 10g red bell pepper · 5g onion · 5g ground crayfish · 100-150ml stock · Salt, seasoning cubes", "method": "Boil the assorted meats with onion and seasoning until tender, keeping the stock. Fry the blended tomato and pepper in palm oil, stir in the ground egusi and crayfish and cook until it thickens and the oil rises. Add the meats and stock and simmer, then stir in the chopped greens for the last few minutes. Season.", "cookTime": "40–60 min", "kcal": "~350–450 kcal", "nutrition": "Protein 25-30g, Fat 20g, Carbs 10g, high in iron & vitamins.", "storage": "Fridge 3-4 days; freezes well. Reheats beautifully; pair with fresh swallow.", "chefNotes": "Mix egusi with water into paste before adding. Ugu (pumpkin) leaves instead of spinach if you can get them.", "pairsWith": "Pounded yam (iyan), eba, or fufu.", "trivia": "Egusi is made from dried melon seeds; beloved across Nigeria with regional variations in greens and proteins.", "howThisFeels": "Thick with ground melon seed and assorted meats — the rich soup every region claims best.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-suya", "name": "Suya", "nameAlt": "Spicy Grilled Skewers", "aliases": [], "course": "starter", "type": ["starter", "main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["street-food"], "ingredients": "150g beef (sirloin or rump, thinly sliced) · 10g yaji spice mix (peanuts, ginger, chili, etc.) · 5ml peanut oil · 1g salt · onion, tomato slices for serving", "method": "Coat the thinly sliced beef in the yaji spice mix and a little oil; rest. Thread onto skewers and grill over hot coals, dusting with more yaji, until charred and just cooked. Serve with sliced onion and tomato.", "cookTime": "15–25 min (grill)", "kcal": "~280–350 kcal", "nutrition": "Protein 30g, Fat 15g.", "storage": "Best fresh; fridge 2 days. Chop into fried rice or wraps.", "chefNotes": "Thin slices cook fast; use open flame for authenticity.", "pairsWith": "Sliced onions, tomatoes, and bread.", "trivia": "Hausa-origin street food sold everywhere; yaji spice blend is addictive.", "howThisFeels": "Peanut-spiced meat off a smoky grill — the yaji-dusted skewer you smell before you see.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-pounded-yam", "name": "Pounded Yam", "nameAlt": "Iyan", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["everyday"], "ingredients": "200g yam (peeled & boiled) · 50-80ml hot water (as needed)", "method": "Boil the peeled yam until very soft. Pound (or process) with a little hot water until smooth, stretchy and lump-free. Shape into a mound and serve hot with soup.", "cookTime": "30–40 min", "kcal": "~250–300 kcal", "nutrition": "Carbs 55g, some potassium.", "storage": "Best fresh. Fridge 1-2 days. Re-pound or fry.", "chefNotes": "Pound until stretchy and smooth.", "pairsWith": "Egusi, okra, or vegetable soups.", "trivia": "Classic \"swallow\" eaten by hand; a staple in many homes.", "howThisFeels": "Smooth, stretchy and eaten by hand — the 'swallow' that catches every drop of soup.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-moi-moi", "name": "Moi Moi", "nameAlt": "Moin Moin", "aliases": [], "course": "side", "type": ["side", "starter"], "diet": ["pescatarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration"], "ingredients": "60g peeled beans (blended) · 20ml vegetable oil · 20g bell pepper · 10g onion · 1 egg (optional, 1/12 egg scaled) · 5g ground crayfish · Salt, seasoning", "method": "Blend the peeled beans with the pepper and onion to a smooth batter, then stir in the oil, crayfish and seasoning. Pour into greased moulds or leaf wraps, top with egg if using, and steam 45–60 min until firm and set.", "cookTime": "45–60 min (steaming)", "kcal": "~220–280 kcal", "nutrition": "Protein 12g, high fiber.", "storage": "Fridge 3 days.", "chefNotes": "Use banana leaves or foil cups.", "pairsWith": "Jollof rice, fried rice.", "trivia": "Popular at parties; delicate texture requires careful blending.", "howThisFeels": "Steamed bean pudding, soft and savoury — the delicate parcel that crowns a party plate.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-pepper-soup", "name": "Pepper Soup", "nameAlt": "Spicy Broth", "aliases": [], "course": "main", "type": ["main", "soup"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration"], "ingredients": "150g goat meat · 5g pepper soup spice mix · 20g onion · 5g Scotch bonnet · 5g ground crayfish · 200ml water · Scent leaves (uziza/utazi)", "method": "Bring the meat or fish to a simmer with the onion, Scotch bonnet, crayfish and pepper-soup spice in water or stock. Cook until tender and the broth is fiery and fragrant. Add the scent leaves at the end and season.", "cookTime": "45–90 min (depending on protein)", "kcal": "~250–350 kcal", "nutrition": "Protein 25g, low carb.", "storage": "Fridge 3-4 days.", "chefNotes": "Simmer gently for clear broth. Stewing beef or firm fish work in place of goat meat.", "pairsWith": "Alone or with yam/rice.", "trivia": "Often medicinal; eaten to \"clear the system\" or celebrate.", "howThisFeels": "Fiery, fragrant and clearing — the broth eaten to celebrate or to set you right.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-akara", "name": "Akara", "nameAlt": "Bean Cakes", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["breakfast", "street-food"], "ingredients": "60g peeled black-eyed peas (blended) · 10g onion · 10g green pepper · Salt, seasoning · Oil for frying (15ml absorbed)", "method": "Blend the peeled black-eyed peas with the onion and pepper to a thick, smooth batter and whisk well to aerate. Season, then drop spoonfuls into hot oil and fry until golden brown and puffed; drain.", "cookTime": "20–30 min", "kcal": "~220–280 kcal", "nutrition": "Protein 10g, Carbs 20g.", "storage": "Best fresh.", "chefNotes": "Whisk batter for fluffiness.", "pairsWith": "Pap (ogi) for breakfast or bread.", "trivia": "Classic street breakfast food; simple yet addictive.", "howThisFeels": "Golden bean cakes hissing in oil — the simple street breakfast that's quietly addictive.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-efo-riro", "name": "Efo Riro", "nameAlt": "Vegetable Stew", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["everyday"], "ingredients": "150g stewing beef (or 'assorted meat': beef + tripe/shaki + cow-skin/ponmo + a little smoked fish) · 200g spinach (chopped) · 50g tomatoes (blended) · 30g red bell pepper (blended) · 15ml palm oil · 5g onion · 5g ground crayfish · 5g Scotch bonnet pepper · 100ml stock · Salt, seasoning cubes", "method": "Boil the assorted meats and fish with seasoning until tender. Fry the blended tomato, pepper and Scotch bonnet in palm oil with the onion and crayfish until reduced. Add the meats with a little stock, then fold in the chopped greens and cook briefly so they stay vibrant. Season.", "cookTime": "35–50 min", "kcal": "~320–420 kcal", "nutrition": "Protein 25g, Fat 18g, Carbs 12g, very high in Vitamins A, C & iron.", "storage": "Fridge 3-4 days; freezes well. Reheats excellently; serve with fresh swallow.", "chefNotes": "Add leaves at the end to retain color and nutrients. Efirin (scent leaf) instead of spinach for authenticity.", "pairsWith": "Amala, eba, or pounded yam.", "trivia": "A staple in Yoruba households; often cooked by women for Sunday family meals and special occasions.", "howThisFeels": "Spinach rich with meat and stockfish — the Yoruba Sunday pot, cooked with love.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-nigerian-fried-rice", "name": "Nigerian Fried Rice", "nameAlt": "Spiced Vegetable Fried Rice", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration"], "ingredients": "80g long-grain rice (parboiled) · 50g mixed vegetables (carrots, peas, sweet corn) · 40g chicken (diced) · 15ml vegetable oil · 30g onion · 5g garlic · 2g curry powder · 2g thyme · 100ml chicken stock · Salt", "method": "Parboil the rice and drain. Stir-fry the diced chicken or beef, then the onion, garlic and mixed vegetables with the curry and thyme. Add the rice and a little stock and toss over high heat until dry, fragrant and just tender.", "cookTime": "40–55 min", "kcal": "~420–480 kcal", "nutrition": "Carbs 60g, Protein 15g, Fat 14g.", "storage": "Fridge 3-4 days. Excellent stir-fried the next day.", "chefNotes": "Parboil rice first; fry vegetables lightly for crunch. Beef works in place of chicken.", "pairsWith": "Jollof rice (for variety), coleslaw, and fried chicken.", "trivia": "The ultimate Nigerian party rice — every cook has their secret recipe for the perfect color and taste.", "howThisFeels": "Curry-gold rice flecked with vegetables — the party staple every cook guards a secret for.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-okra-soup", "name": "Okra Soup", "nameAlt": "Draw Soup", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": [], "ingredients": "150g stewing beef (+ a little smoked fish) · 150g fresh okra (sliced) · 15ml palm oil · 5g onion · 5g ground crayfish · 5g Scotch bonnet · 100ml stock · Uziza leaves (optional)", "method": "Simmer the assorted meats and fish in stock with the onion and crayfish until tender. Add the sliced okra and palm oil and cook 5–10 min, stirring, for the prized 'draw' texture. Add uziza leaves and Scotch bonnet; season.", "cookTime": "35–50 min", "kcal": "~280–360 kcal", "nutrition": "Protein 22g, Fat 12g, high fiber & vitamins.", "storage": "Fridge 3 days. Add water when reheating to restore texture.", "chefNotes": "Slice okra thinly and stir well for maximum viscosity.", "pairsWith": "Eba (garri), semolina, or pounded yam.", "trivia": "The sliminess is the point — it's considered highly nutritious and good for pregnant women in many cultures.", "howThisFeels": "Gloriously drawing and slippery — a soup that's all the better for how it stretches off your spoon.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-amala", "name": "Amala", "nameAlt": "Yam Flour Swallow", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": [], "ingredients": "80g yam flour (elubo) · 300ml hot water", "method": "Bring the water to a boil. Sprinkle in the yam flour, stirring hard and folding continuously over low heat until smooth, stretchy and lump-free. Shape and serve hot with soup.", "cookTime": "10–15 min", "kcal": "~220–260 kcal", "nutrition": "Carbs 50g, some fiber.", "storage": "Best fresh. Fridge 1-2 days. Reheat with hot water and stir.", "chefNotes": "Stir vigorously over heat until smooth and stretchy.", "pairsWith": "Efo riro, gbegiri, or abula soup.", "trivia": "Iconic among the Yoruba; the dark color comes from sun-dried yam.", "howThisFeels": "Dark, smooth and made from sun-dried yam — the Yoruba 'swallow' with a flavour all its own.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-gbegiri-soup", "name": "Gbegiri Soup", "nameAlt": "Beans Soup", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Nigeria", "occasion": [], "ingredients": "60g brown beans (cooked & blended) · 100g stewing beef · 15ml palm oil · 20g tomatoes · 10g red bell pepper · 5g onion · 5g ground crayfish · Stock as needed", "method": "Cook the brown beans until very soft, then blend smooth (or press through a sieve). Fry the blended tomato and pepper in palm oil with the onion and crayfish, add the bean purée and stock, and simmer with the cooked meats to a smooth, thick soup. Season.", "cookTime": "50–70 min", "kcal": "~300–380 kcal", "nutrition": "Protein 18g, high fiber.", "storage": "Fridge 3-4 days.", "chefNotes": "Blend beans smoothly for silky texture.", "pairsWith": "Amala or eba.", "trivia": "Often paired with abula (combination with efo) in Oyo State traditions.", "howThisFeels": "Smooth blended beans, pale and comforting — the Oyo classic that loves company on the plate.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-puff-puff", "name": "Puff Puff", "nameAlt": "Fried Sweet Dough Balls", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration", "breakfast", "street-food"], "ingredients": "60g plain flour · 10g sugar · 3g yeast · 80ml warm water · Pinch salt · Oil for frying (20ml absorbed)", "method": "Mix the flour, sugar, yeast and salt with warm water into a thick, smooth batter and prove until bubbly, about 1 hr. Drop spoonfuls into hot oil and fry, turning, until deep golden and round; drain.", "cookTime": "30–45 min (including frying)", "kcal": "~280–340 kcal", "nutrition": "Carbs 40g, Fat 12g.", "storage": "Best fresh; fridge 2 days.", "chefNotes": "Let batter rise properly; fry at medium heat.", "pairsWith": "Alone or with chilled drink.", "trivia": "Sold by street vendors everywhere; perfect for breakfast or as party finger food.", "howThisFeels": "Sweet, airy fried dough off a street tray — finger-food joy for any gathering.", "servings": 1, "sharedWith": ""},
  {"id": "nigeria-chin-chin", "name": "Chin Chin", "nameAlt": "Crunchy Fried Dough Snack", "aliases": [], "course": "dessert", "type": ["snack", "dessert"], "diet": ["vegetarian"], "cuisine": "west-africa", "country": "Nigeria", "occasion": ["celebration", "street-food", "everyday"], "ingredients": "60g plain flour · 10g butter · 15g sugar · 1/4 egg · 20ml milk · Pinch nutmeg · Oil for frying", "method": "Rub the butter into the flour with the sugar and nutmeg, then mix in the egg and milk to a firm dough. Roll thin, cut into small squares, and deep-fry until golden and crunchy; drain and cool.", "cookTime": "40–50 min", "kcal": "~240–300 kcal", "nutrition": "Carbs 35g, Fat 12g.", "storage": "Airtight container up to 2 weeks.", "chefNotes": "Cut into small diamonds; fry in batches. Margarine works in place of butter.", "pairsWith": "With zobo drink or tea.", "trivia": "Popular homemade snack for visits and celebrations — every Nigerian home has its own recipe variation.", "howThisFeels": "Crunchy fried squares, lightly sweet — the tin of homemade snack kept ready for visitors.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-fufu", "name": "Fufu", "nameAlt": "Pounded Cassava & Plantain", "aliases": [], "course": "side", "type": ["main", "side"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["everyday"], "ingredients": "150g cassava (peeled) · 100g green plantain (peeled) · Water for boiling", "method": "Boil the cassava and green plantain until very soft. Pound together (or process) with a little hot water until smooth, stretchy and lump-free. Shape into a ball and serve with soup.", "cookTime": "30–45 min (boiling + pounding)", "kcal": "~280–320 kcal", "nutrition": "Carbs 65g, Protein 4g, low fat, good potassium.", "storage": "Best fresh. Fridge up to 1 day. Reheat by kneading with hot water.", "chefNotes": "Pound until smooth, stretchy, and lump-free.", "pairsWith": "Groundnut soup, light soup, or palm nut soup with protein.", "trivia": "Traditionally pounded by two people (one pounds, one turns); eaten by hand, dipped into soup. Symbol of Ghanaian communal dining.", "howThisFeels": "Pounded soft and stretchy by two pairs of hands — dipped, not chewed, into a steaming soup.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-groundnut-soup", "name": "Groundnut Soup", "nameAlt": "Peanut Soup", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Ghana", "occasion": [], "ingredients": "30g natural peanut butter (or ground peanuts) · 150g chicken · 50g tomatoes (blended) · 30g onion · 5g ginger · 5g garlic · 10ml palm oil · 200ml stock · Chili, salt, seasoning", "method": "Brown the chicken or meat, then simmer with the blended tomato, onion, ginger and garlic in stock until tender. Loosen the peanut butter with a little stock, stir it in, and simmer 20–30 min until rich and the oil rises. Season with chilli and salt.", "cookTime": "45–60 min", "kcal": "~380–450 kcal", "nutrition": "Protein 25-30g, Fat 22g, Carbs 15g, high in niacin and magnesium.", "storage": "Fridge 3-4 days; freezes well. Flavors improve next day; thin with stock if needed.", "chefNotes": "Whisk peanut butter smoothly into soup. Stewing beef works in place of chicken.", "pairsWith": "Fufu, rice, or banku.", "trivia": "Also called nkate nkwan; a favorite for special occasions and \"comfort\" meals.", "howThisFeels": "Peanut-rich and deeply savoury — the comfort bowl Ghana saves for special days.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-waakye", "name": "Waakye", "nameAlt": "Rice & Beans", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["breakfast", "street-food"], "ingredients": "60g rice · 40g black-eyed peas (soaked) · 5g baking soda (for color) · 150ml water · Salt", "method": "Soak the black-eyed peas, then boil with the rice and the sorghum leaves (or a little baking soda) in salted water or stock until both are tender and tinged red-brown. Fluff and serve with the usual sides.", "cookTime": "50–70 min", "kcal": "~320–380 kcal", "nutrition": "Carbs 60g, Protein 12g, Fiber high.", "storage": "Fridge 3 days. Reheat with splash of water.", "chefNotes": "Cook beans first, then add rice. Sorghum (waakye) leaves give the traditional red colour in place of baking soda.", "pairsWith": "Shito (spicy sauce), fried fish, spaghetti, gari, avocado, boiled egg.", "trivia": "Popular breakfast/street food; the purple color comes from waakye leaves. A complete meal in one plate.", "howThisFeels": "Rice and beans stained purple by waakye leaves — a whole breakfast in one parcel.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-banku", "name": "Banku", "nameAlt": "Fermented Corn & Cassava Dough", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["everyday"], "ingredients": "80g corn dough · 40g cassava dough · 300ml water · Salt", "method": "Mix the corn and cassava dough with the water and salt into a smooth slurry. Cook over low heat, stirring and folding hard with a wooden spoon, until thick, smooth and slightly tangy. Shape into balls and serve hot.", "cookTime": "20–30 min", "kcal": "~250–300 kcal", "nutrition": "Carbs 55g, some B vitamins from fermentation.", "storage": "Best fresh. Reheat by stirring with hot water.", "chefNotes": "Stir vigorously to avoid lumps; sour taste is desired.", "pairsWith": "Grilled tilapia with shito and pepper sauce.", "trivia": "Fermentation gives it a unique tangy flavor; a staple in coastal and southern Ghana.", "howThisFeels": "Tangy fermented corn and cassava — the slightly-sour staple of the southern coast.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-red-red", "name": "Red Red", "nameAlt": "Beans Stew", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["everyday"], "ingredients": "100g cooked black-eyed peas · 30ml palm oil · 50g tomatoes (blended) · 30g onion · 3g garlic · 2g ginger · Chili, salt, shrimp powder (optional) · 100g fried ripe plantain (side)", "method": "Fry the onion, ginger and garlic in palm oil, add the blended tomato and chilli and cook down. Stir in the cooked black-eyed peas (and shrimp powder) and simmer until thick. Serve with fried ripe plantain.", "cookTime": "35–45 min", "kcal": "~380–450 kcal", "nutrition": "Protein 15g, Fat 18g, high fiber & iron.", "storage": "Fridge 4 days. Excellent reheated.", "chefNotes": "Use ripe plantains for sweetness contrast.", "pairsWith": "Gari, rice, or alone.", "trivia": "Named for the red palm oil; a hearty, affordable everyday meal.", "howThisFeels": "Black-eyed peas glowing in red palm oil — hearty, affordable and unforgettable.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-kelewele", "name": "Kelewele", "nameAlt": "Spiced Fried Plantain", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["street-food"], "ingredients": "200g ripe plantain (sliced) · 5g ginger (grated) · 5g chili flakes · 2g cayenne · Pinch salt · 15ml oil for frying", "method": "Toss the sliced ripe plantain with the grated ginger, chilli, pepper and salt. Deep- or shallow-fry in hot oil until caramelised and golden at the edges; drain. Serve hot.", "cookTime": "20–25 min", "kcal": "~220–280 kcal", "nutrition": "Carbs 35g, Fat 10g.", "storage": "Best fresh.", "chefNotes": "Marinate 30 minutes before frying.", "pairsWith": "As snack or with waakye/red red.", "trivia": "Popular street food, especially at night markets; the spices make it addictive.", "howThisFeels": "Ripe plantain spiced with ginger and chilli — the sweet-hot snack of the night market.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-jollof-rice", "name": "Jollof Rice", "nameAlt": "Ghanaian Style", "aliases": [], "course": "main", "type": ["main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["celebration"], "ingredients": "80g long-grain rice · 70g tomatoes · 30g red bell pepper · 40g onion · 15ml vegetable oil · 5g tomato paste · 150ml stock · Spices (thyme, curry, bay leaf, chili)", "method": "Blend the tomatoes and peppers and fry with the tomato paste and onion in oil to a rich base with the spices. Stir in the rice and stock, cover, and cook on low until absorbed and tender. Rest and fluff — Ghanaian jollof is often made with fragrant long-grain rice.", "cookTime": "45–60 min", "kcal": "~390–460 kcal", "nutrition": "Carbs 65g, Protein 8g, Fat 12g.", "storage": "Fridge 3-4 days. Fry the next day for \"jollof fried rice.\"", "chefNotes": "Use Ghanaian-style with more heat and spices. Palm oil instead of vegetable oil is more traditional.", "pairsWith": "Grilled chicken, coleslaw, shito.", "trivia": "Central to Ghanaian parties and celebrations; Ghanaians proudly claim the best version.", "howThisFeels": "Smoky, fragrant and proudly Ghanaian — the version locals will swear is the real one.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-palm-nut-soup", "name": "Palm Nut Soup", "nameAlt": "Abenkwan", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Ghana", "occasion": ["celebration"], "ingredients": "150g chicken · 150ml palm nut extract (or 40g palm nut concentrate + water) · 50g tomatoes (blended) · 30g onion · 5g ginger · 5g garlic · 10ml palm oil · 200ml water · Chili, salt, seasoning", "method": "Simmer the chicken or fish with the onion, ginger and garlic until tender. Add the palm nut extract, blended tomato and stock and simmer 30–40 min until rich and the oil floats. Season with chilli and salt.", "cookTime": "50–70 min", "kcal": "~380–460 kcal", "nutrition": "Protein 25g, Fat 25g, Carbs 12g, high in Vitamin A.", "storage": "Fridge 3-4 days; freezes well. Reheat gently and stir well; thins slightly when reheated.", "chefNotes": "Simmer slowly to develop deep flavor; remove foam from surface. Stewing beef or firm white fish work in place of chicken.", "pairsWith": "Fufu, banku, or rice.", "trivia": "Often prepared for special occasions and festive gatherings; considered a luxurious soup in many Ghanaian homes.", "howThisFeels": "Deep red palm-nut richness — the luxurious soup reserved for festive tables.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-light-soup", "name": "Light Soup", "nameAlt": "Spicy Tomato Broth", "aliases": [], "course": "main", "type": ["main"], "diet": [], "cuisine": "west-africa", "country": "Ghana", "occasion": [], "ingredients": "150g fish (tilapia or mackerel) · 80g tomatoes (blended) · 40g onion · 5g ginger · 5g garlic · 5g Scotch bonnet pepper · 200ml water · Salt, seasoning cubes", "method": "Simmer the onion, ginger, garlic, Scotch bonnet and blended tomato in water or stock to a fragrant broth. Add the fish or chicken and cook until tender and the soup is light but flavourful. Season.", "cookTime": "35–50 min", "kcal": "~220–320 kcal (depending on protein)", "nutrition": "Protein 25g, Carbs 10g, low fat.", "storage": "Fridge 3 days. Excellent next day; add fresh chili when reheating.", "chefNotes": "Keep it light and brothy; strain if preferred smoother. Chicken works in place of fish.", "pairsWith": "Fufu or plain rice.", "trivia": "Called “Nsuo” in Twi; commonly eaten when someone is unwell as it’s believed to be restorative.", "howThisFeels": "Clear, peppery and restorative — the broth Ghana cooks when someone needs mending.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-kontomire-stew", "name": "Kontomire Stew", "nameAlt": "Palava Sauce", "aliases": [], "course": "main", "type": ["main"], "diet": ["pescatarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["everyday"], "ingredients": "200g kontomire (cocoyam leaves) · 40g smoked fish · 30ml palm oil · 50g tomatoes (blended) · 30g onion · 3g garlic · 2g ginger · 5g chili · Salt, seasoning", "method": "Boil and chop the cocoyam leaves (or spinach). Fry the onion, ginger, garlic and chilli in palm oil, add the blended tomato and smoked fish, then the greens, and simmer until thick. Season.", "cookTime": "30–40 min", "kcal": "~280–350 kcal", "nutrition": "Protein 15g, Fat 18g, high in iron and Vitamins A & K.", "storage": "Fridge 3-4 days. Reheats well; pairs nicely with leftover fufu.", "chefNotes": "Cook leaves thoroughly to remove bitterness. Spinach works in place of kontomire; shrimp instead of smoked fish.", "pairsWith": "Kenkey, banku, or boiled yam.", "trivia": "Also known as Palava Sauce; a classic everyday dish that shows resourceful use of local greens.", "howThisFeels": "Cocoyam leaves cooked down with egusi — 'palava sauce', everyday and resourceful.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-kenkey", "name": "Kenkey", "nameAlt": "Fermented Corn Dumpling", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": [], "ingredients": "100g fermented corn dough · 30g corn flour (for dusting) · banana leaves (for wrapping) · Salt to taste", "method": "Mix the fermented corn dough with a little corn flour and salt and partly cook to a stiff paste. Wrap portions in banana leaves or corn husks and steam or boil 1–2 hrs until firm and cooked through. Serve with pepper sauce and fish.", "cookTime": "40–60 min (steaming)", "kcal": "~240–290 kcal", "nutrition": "Carbs 55g, some probiotics from fermentation.", "storage": "Fridge 2-3 days. Re-steam or fry slices.", "chefNotes": "Form into balls and wrap tightly before steaming.", "pairsWith": "Shito, fried fish, and pepper sauce.", "trivia": "A Ga-Adangbe specialty; “Ga kenkey” is firmer while “Fante kenkey” is softer.", "howThisFeels": "Fermented corn dough wrapped and steamed — sour, firm and made for the coast.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-tuo-zaafi", "name": "Tuo Zaafi", "nameAlt": "TZ", "aliases": [], "course": "side", "type": ["side", "main"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["everyday"], "ingredients": "80g millet flour (or corn flour) · 300ml water · Pinch salt", "method": "Make a thin slurry from part of the millet (or corn) flour and water. Bring the rest of the water to a boil, stir in the slurry, then gradually add the remaining flour, beating hard until smooth, thick and stretchy. Shape and serve with soup.", "cookTime": "15–20 min", "kcal": "~230–270 kcal", "nutrition": "Carbs 50g, gluten-free.", "storage": "Best fresh. Reheat with hot water and stir.", "chefNotes": "Stir continuously over heat until very smooth.", "pairsWith": "Ayoyo (jute leaf) soup or okro soup.", "trivia": "Staple food of the northern regions; eaten with hands and valued for its filling quality.", "howThisFeels": "Soft, filling and northern — the 'TZ' eaten by hand with a generous soup.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-bofrot", "name": "Bofrot", "nameAlt": "Puff Puff", "aliases": [], "course": "starter", "type": ["starter", "snack"], "diet": ["vegan", "vegetarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": ["street-food"], "ingredients": "60g plain flour · 10g sugar · 3g active yeast · 80ml warm water · Pinch nutmeg (optional) · Pinch salt · Oil for frying (20ml absorbed)", "method": "Mix the flour, sugar, yeast, nutmeg and salt with warm water into a thick batter and prove until risen and bubbly. Drop rounds into hot oil and fry, turning, until deep golden; drain.", "cookTime": "35–45 min", "kcal": "~280–340 kcal", "nutrition": "Carbs 40g, Fat 12g.", "storage": "Best fresh; can keep 1 day.", "chefNotes": "Allow batter to rise 1-2 hours; fry at medium temperature.", "pairsWith": "As snack with hot tea or alone.", "trivia": "Extremely popular street food; sold warm in the evenings across Ghana.", "howThisFeels": "Warm, round and sweet — the evening fried dough sold from glowing street stalls.", "servings": 1, "sharedWith": ""},
  {"id": "ghana-shito", "name": "Shito", "nameAlt": "Black Pepper Sauce", "aliases": [], "course": "side", "type": ["condiment", "side"], "diet": ["pescatarian"], "cuisine": "west-africa", "country": "Ghana", "occasion": [], "ingredients": "30ml vegetable oil · 20g dried shrimp (ground) · 15g onion (blended) · 5g garlic · 5g ginger · 10g chili powder · 5g tomato paste · Salt, seasoning", "method": "Fry the blended onion, garlic and ginger in plenty of oil until dark and fragrant. Add the ground dried shrimp, chilli powder and tomato paste and cook low and slow, stirring, until deep brown-black and the oil separates. Cool — it keeps for weeks as a condiment.", "cookTime": "25–35 min", "kcal": "~180–220 kcal", "nutrition": "Fat 18g, Protein 8g.", "storage": "Fridge 2-3 weeks in airtight jar.", "chefNotes": "Cook slowly until very dark; stir frequently.", "pairsWith": "Kenkey, banku, waakye, or grilled fish.", "trivia": "Essential Ghanaian condiment; every household has its own heat level and secret recipe.", "howThisFeels": "Dark, smoky, shrimp-spiked pepper sauce — every Ghanaian home's secret weapon.", "servings": 1, "sharedWith": ""}
